/* ============================================================
   DARMOK kanji database — per-character breakdowns for all 400
   curriculum kanji. Keyed by the kanji. Entry:
     { m: meaning, on:[音 katakana], kun:[訓 hiragana, okurigana after '.'],
       rad:[{c: component, m: gloss}], mn: mnemonic, cn: Japan-vs-China note ("" if none) }
   Authored + adversarially accuracy-verified (readings, radicals, and every
   Japan-vs-China note fact-checked; unconfirmable notes dropped). GENERATED —
   see wrk_docs HLD; do not hand-edit piecemeal.
   ============================================================ */
DK.KANJI = {
  "私": {"m":"I, me (also: private, personal)","on":["シ"],"kun":["わたし","わたくし"],"rad":[{"c":"禾","m":"grain / rice plant"},{"c":"厶","m":"private, self / to enclose"}],"mn":"The grain (禾) you fence off for yourself (厶) — what is private, and so the word for 'I'.","cn":"Chinese 私 (sī) means private/personal/selfish but is never the pronoun 'I' (that's 我); Japanese kept the 'private' sense and made 私 the everyday word for 'I'."},
  "学": {"m":"study, learning; science, -ology","on":["ガク"],"kun":["まな.ぶ"],"rad":[{"c":"⺍","m":"busy hands, above"},{"c":"冖","m":"roof / cover"},{"c":"子","m":"child"}],"mn":"A child (子) under the schoolhouse roof (冖) with hands busy (⺍) above — a child at study, learning.","cn":"Japan's shinjitai 学 is identical to China's simplified 学; the traditional form (still used in Taiwan/Hong Kong) is 學."},
  "生": {"m":"life, birth; to live; raw, fresh; student (in 学生)","on":["セイ","ショウ"],"kun":["い.きる","う.まれる","なま"],"rad":[{"c":"屮","m":"a sprouting plant"},{"c":"一","m":"the ground"}],"mn":"A young plant (屮) pushing up out of the earth (一) — life, growth, birth.","cn":""},
  "先": {"m":"previous, ahead, before; earlier; tip, point","on":["セン"],"kun":["さき"],"rad":[{"c":"土","m":"a foot on the ground (top)"},{"c":"儿","m":"human legs, walking"}],"mn":"A foot on the ground (土) striding on the legs (儿) — one who steps out ahead: before, first.","cn":"In compound 先生 this means 'teacher/doctor' in Japanese (sensei), but 'Mr./sir/husband' in Chinese (xiānsheng)."},
  "医": {"m":"medicine; doctor; healing","on":["イ"],"kun":[],"rad":[{"c":"匚","m":"a box / open container"},{"c":"矢","m":"arrow"}],"mn":"Draw the arrow (矢) out of its quiver-box (匚) to treat the wound — medicine, the doctor's art.","cn":"医 is the shinjitai (and PRC-simplified) form; the traditional character is 醫, which adds 殳 (top-right) and 酉 (wine, once used as medicine) beneath."},
  "者": {"m":"person; one who…, -er (suffix for people)","on":["シャ"],"kun":["もの"],"rad":[{"c":"耂","m":"old man / earth-and-sprout top"},{"c":"日","m":"sun / to say"}],"mn":"Someone (者) toiling under the sun (日) — 'the person', the one who does (医者 doctor, 学者 scholar).","cn":"The Japanese jōyō form 者 drops a small dot that the traditional (Kangxi) form carries (the same simplification appears in 都, 暑, 署)."},
  "艦": {"m":"warship, naval vessel","on":["カン"],"kun":[],"rad":[{"c":"舟","m":"boat"},{"c":"監","m":"to oversee, keep watch"}],"mn":"A boat (舟) built to keep watch and command (監) over the sea — a warship (軍艦; 艦長 = ship's captain).","cn":""},
  "長": {"m":"long; leader, chief, head; senior","on":["チョウ"],"kun":["なが.い"],"rad":[{"c":"長","m":"long, flowing hair of an elder"}],"mn":"A picture of an elder's long, streaming hair — 'long', and by extension the eldest, the chief or leader.","cn":"Japanese keeps the traditional 長; the Chinese simplified form is 长."},
  "日": {"m":"day; sun","on":["ニチ","ジツ"],"kun":["ひ","か"],"rad":[{"c":"日","m":"the sun, with a mark in its center"}],"mn":"A picture of the sun (a circle with a stroke inside) — the sun, and the 'day' it marks out.","cn":""},
  "本": {"m":"book; origin, source; main; counter for long objects","on":["ホン"],"kun":["もと"],"rad":[{"c":"木","m":"tree"},{"c":"一","m":"a mark at the base"}],"mn":"A tree (木) with a stroke (一) drawn across its roots — the origin/base; hence 'main', and the everyday word for 'book'.","cn":"Japanese 本 is the ordinary word for 'book'; in Chinese 'book' is 書/书, and 本 (běn) means 'root/origin' or acts as a measure word for volumes."},
  "語": {"m":"language; word; to talk, narrate","on":["ゴ"],"kun":["かた.る","かた.らう"],"rad":[{"c":"言","m":"speech / words"},{"c":"吾","m":"I, me (phonetic 'go')"}],"mn":"Speech (言) that comes from me (吾) and is shared — words, and the language they make (日本語 = Japanese).","cn":""},
  "英": {"m":"England, English; brilliant, outstanding; hero","on":["エイ"],"kun":[],"rad":[{"c":"艹","m":"plant / grass"},{"c":"央","m":"center (phonetic)"}],"mn":"The finest flower (艹) blooming at the very center (央) — outstanding, brilliant; also 'England' (英語 = English).","cn":""},
  "茶": {"m":"tea","on":["チャ","サ"],"kun":[],"rad":[{"c":"艹","m":"plant / grass"},{"c":"余","m":"roof over a small tree (人 + 木)"}],"mn":"A leafy plant (艹) grown as a low bush of wood (木) that people (人) pick — the tea shrub: tea.","cn":""},
  "水": {"m":"water","on":["スイ"],"kun":["みず"],"rad":[{"c":"水","m":"a stream with splashes on each side"}],"mn":"A central current with droplets flying off either bank — flowing water.","cn":""},
  "誰": {"m":"who","on":[],"kun":["だれ"],"rad":[{"c":"言","m":"speech / to speak"},{"c":"隹","m":"small (short-tailed) bird"}],"mn":"You speak up (言) to a little bird (隹) and ask 'and who are you?' — 誰 = who.","cn":""},
  "何": {"m":"what; how many/how much (counter prefix, なん-)","on":["カ"],"kun":["なに","なん"],"rad":[{"c":"亻","m":"person"},{"c":"可","m":"can, may (phonetic)"}],"mn":"A person (亻) shouldering a load stops and asks 'what is this?' (可, phonetic) — 何 = what.","cn":""},
  "猫": {"m":"cat","on":["ビョウ"],"kun":["ねこ"],"rad":[{"c":"犭","m":"beast / animal"},{"c":"苗","m":"rice seedling (phonetic 'byō')"}],"mn":"The little beast (犭) that guards the rice seedlings (苗) from mice — the cat.","cn":"Japanese 猫 uses the beast radical 犭; the traditional Chinese form is 貓, written with 豸 instead."},
  "犬": {"m":"dog","on":["ケン"],"kun":["いぬ"],"rad":[{"c":"大","m":"big (a person, arms out)"},{"c":"丶","m":"a small mark — the dog's ear"}],"mn":"A big creature (大) with one extra flick (丶) for a pricked ear — the dog.","cn":""},
  "人": {"m":"person, human being","on":["ジン","ニン"],"kun":["ひと"],"rad":[{"c":"人","m":"a standing figure with two legs"}],"mn":"A simple picture of a person striding on two legs — a human being.","cn":""},
  "友": {"m":"friend","on":["ユウ"],"kun":["とも"],"rad":[{"c":"𠂇","m":"a hand (upper)"},{"c":"又","m":"a hand (lower)"}],"mn":"Two hands (𠂇 over 又) reaching the same way, clasped together — friends.","cn":""},
  "達": {"m":"to reach, attain, arrive; -tachi (pluralizes people)","on":["タツ"],"kun":[],"rad":[{"c":"辶","m":"to move / walk the road"},{"c":"羍","m":"a lamb (大 over 羊)"}],"mn":"Walk the road (辶) leading a sure-footed lamb (羍) safely through — to reach; also pluralizes people (友達 friends, 私達 we).","cn":"Japanese keeps 達; the Chinese simplified form is 达."},
  "名": {"m":"name; reputation, fame; counter for people","on":["メイ","ミョウ"],"kun":["な"],"rad":[{"c":"夕","m":"evening, dusk"},{"c":"口","m":"mouth"}],"mn":"In the dark of evening (夕) you can't be seen, so you call out with your mouth (口) — your name (名前 = name).","cn":""},
  "前": {"m":"front; before; earlier, previous","on":["ゼン"],"kun":["まえ"],"rad":[{"c":"丷","m":"two strokes, on top"},{"c":"月","m":"flesh / boat"},{"c":"刂","m":"knife"}],"mn":"A knife (刂) trimming at the boat's flesh-and-timber prow (月) — the part that goes ahead: the front, before.","cn":""},
  "紅": {"m":"crimson, deep red; rouge","on":["コウ","ク"],"kun":["べに","くれない"],"rad":[{"c":"糸","m":"silk thread"},{"c":"工","m":"work, craft (phonetic 'kō')"}],"mn":"Silk thread (糸) skillfully worked (工) and dyed a rich deep red — crimson, rouge (紅茶 = black tea, lit. 'red tea').","cn":"Chinese 紅 (simp. 红, hóng) is the everyday word for 'red'; Japanese everyday 'red' is 赤 (aka), and 紅 means specifically crimson or rouge."},
  "宇": {"m":"eaves, roof; the heavens, space (宇宙 = universe)","on":["ウ"],"kun":[],"rad":[{"c":"宀","m":"roof / house"},{"c":"于","m":"to stretch out (phonetic 'u')"}],"mn":"A roof (宀) that stretches out (于) over everything — the eaves, and by extension the great canopy of heaven: space.","cn":""},
  "宙": {"m":"mid-air, space (as in 宇宙 the universe)","on":["チュウ"],"kun":[],"rad":[{"c":"宀","m":"roof / house"},{"c":"由","m":"reason, cause, from"}],"mn":"Under heaven's roof (宀), things float for a reason (由) — suspended in mid-air, out in space.","cn":""},
  "船": {"m":"ship, boat","on":["セン"],"kun":["ふね","ふな"],"rad":[{"c":"舟","m":"boat"},{"c":"八","m":"eight / split"},{"c":"口","m":"mouth"}],"mn":"A boat (舟) big enough for eight (八) hungry mouths (口) to sail on — a ship.","cn":""},
  "白": {"m":"white; also: blank, to state (告白)","on":["ハク","ビャク"],"kun":["しろ","しろ.い","しら"],"rad":[{"c":"丿","m":"a ray / drop of light"},{"c":"日","m":"sun"}],"mn":"A single ray (丿) of light striking the sun (日) — blindingly white.","cn":""},
  "駅": {"m":"(train / railway) station","on":["エキ"],"kun":[],"rad":[{"c":"馬","m":"horse"},{"c":"尺","m":"measure, a shaku (unit of length)"}],"mn":"Once horses (馬) were swapped by the measured mile (尺) at relay posts — today that post is the train station.","cn":"Japanese 駅 (eki) is the everyday word for train station. Chinese uses 站 (zhàn); the old relay-post character was 驛 / 驿 (yì), from which Japan's 駅 was simplified."},
  "校": {"m":"school; also: proofreading (校正)","on":["コウ"],"kun":[],"rad":[{"c":"木","m":"tree / wood"},{"c":"交","m":"cross, mix, exchange"}],"mn":"Timber (木) crossbeams (交) lashed together frame the schoolhouse — school.","cn":""},
  "家": {"m":"house, home; family; expert / -ist (専門家)","on":["カ","ケ"],"kun":["いえ","や","うち"],"rad":[{"c":"宀","m":"roof / house"},{"c":"豕","m":"pig, boar"}],"mn":"A pig (豕) kept safe under the roof (宀) — the household, the home.","cn":""},
  "今": {"m":"now, this (今日 today, 今 いま)","on":["コン"],"kun":["いま"],"rad":[{"c":"𠆢","m":"roof / cover"},{"c":"丶","m":"a point — this very instant"}],"mn":"A roof (𠆢) pulled down over this single point (丶) in time — now.","cn":""},
  "明": {"m":"bright, clear; also: next (明日 tomorrow)","on":["メイ","ミョウ"],"kun":["あか.るい","あ.ける","あき.らか"],"rad":[{"c":"日","m":"sun"},{"c":"月","m":"moon"}],"mn":"Sun (日) and moon (月) side by side — the brightest, clearest light of all.","cn":""},
  "部": {"m":"part, section, department; club (部活)","on":["ブ"],"kun":[],"rad":[{"c":"立","m":"stand"},{"c":"口","m":"mouth / opening"},{"c":"阝","m":"village, city (right radical, from 邑)"}],"mn":"Stand (立) and speak (口) at the village gate (阝): each district is one section of the town.","cn":""},
  "屋": {"m":"roof; shop, dealer (本屋 bookshop); building","on":["オク"],"kun":["や"],"rad":[{"c":"尸","m":"roof / covering (corpse radical)"},{"c":"至","m":"arrive, reach"}],"mn":"Reach your destination (至) and rest beneath the covering (尸) of a roof — a building, a shop.","cn":"In Japanese, 屋 as a suffix means 'shop / dealer' (本屋 bookshop, パン屋 baker) or a person's trait. Chinese 屋 (wū) only means house / room; a shop there is 店."},
  "木": {"m":"tree, wood","on":["モク","ボク"],"kun":["き","こ"],"rad":[{"c":"木","m":"pictograph of a tree — trunk, branches, roots"}],"mn":"Trunk, spreading branches, and roots below — a tree.","cn":""},
  "山": {"m":"mountain","on":["サン"],"kun":["やま"],"rad":[{"c":"山","m":"pictograph of three mountain peaks"}],"mn":"Three peaks rising side by side — a mountain.","cn":""},
  "川": {"m":"river","on":["セン"],"kun":["かわ"],"rad":[{"c":"川","m":"pictograph of three flowing water-channels"}],"mn":"Three channels of water streaming downhill — a river.","cn":""},
  "公": {"m":"public, official; also: lord, prince","on":["コウ"],"kun":["おおやけ"],"rad":[{"c":"八","m":"eight / to split apart"},{"c":"厶","m":"private, self / cocoon"}],"mn":"Split apart (八) what was private (厶) and share it with all — that makes it public.","cn":"Chinese 公 (gōng) has senses Japanese lacks: 'male' of animals (公雞 rooster, opposite 母) and metric units (公里 = kilometre). Both share the core 'public'."},
  "園": {"m":"garden, park (公園 park, 動物園 zoo)","on":["エン"],"kun":["その"],"rad":[{"c":"囗","m":"enclosure, walls"},{"c":"袁","m":"long robe (phonetic)"}],"mn":"An enclosing wall (囗) around robed (袁) strollers — a garden, a park.","cn":"Simplified Chinese writes 园 — the box holds 元. Japanese keeps the fuller traditional 園, with 袁 inside."},
  "店": {"m":"shop, store (書店 bookshop, 店 みせ)","on":["テン"],"kun":["みせ"],"rad":[{"c":"广","m":"lean-to roof / building"},{"c":"占","m":"occupy, claim / divine"}],"mn":"Under a lean-to roof (广) you stake your claim (占) to a plot — and open a shop.","cn":""},
  "寺": {"m":"(Buddhist) temple","on":["ジ"],"kun":["てら"],"rad":[{"c":"土","m":"earth, ground"},{"c":"寸","m":"hand / measure, an inch"}],"mn":"Hands (寸) tending the earth (土) of the grounds — the temple.","cn":""},
  "時": {"m":"time, hour, o'clock","on":["ジ"],"kun":["とき"],"rad":[{"c":"日","m":"sun"},{"c":"寺","m":"temple"}],"mn":"The sun (日) tracked over the temple (寺) told the monks the hour — time.","cn":"Simplified Chinese writes 时 (日 + 寸); Japanese keeps the full traditional form 時 with 寺."},
  "間": {"m":"interval, space between; among; time (時間)","on":["カン","ケン"],"kun":["あいだ","ま"],"rad":[{"c":"門","m":"gate"},{"c":"日","m":"sun"}],"mn":"Sunlight (日) slipping through a gate (門) — the gap, the space in between.","cn":"Simplified Chinese writes 间 (门 + 日); Japanese keeps 間, the full gate 門 with 日 inside."},
  "上": {"m":"up, above, top; to raise, to climb","on":["ジョウ","ショウ"],"kun":["うえ","うわ","あ.げる","あ.がる","のぼ.る"],"rad":[{"c":"上","m":"an indicator: a mark above the baseline"}],"mn":"A mark set above the baseline — up, above, on top.","cn":""},
  "下": {"m":"down, below, under; to lower, to descend","on":["カ","ゲ"],"kun":["した","さ.げる","さ.がる","くだ.る","お.りる"],"rad":[{"c":"下","m":"an indicator: a mark below the baseline"}],"mn":"A mark hung below the baseline — down, below, beneath.","cn":""},
  "中": {"m":"middle, centre, inside; in the midst of","on":["チュウ","ジュウ"],"kun":["なか"],"rad":[{"c":"中","m":"a line driven through the middle of a box"}],"mn":"A vertical line driven straight through the centre of a box — the middle.","cn":""},
  "後": {"m":"after, later, behind","on":["ゴ","コウ"],"kun":["あと","のち","うし.ろ","おく.れる"],"rad":[{"c":"彳","m":"step, going"},{"c":"幺","m":"short thread / tiny"},{"c":"夂","m":"a foot dragging behind"}],"mn":"A short stride (彳), a tangle of thread (幺), and a foot dragging behind (夂) — you come after, you fall behind.","cn":"Simplified Chinese merged this into 后, which also means 'queen, empress'. Japanese keeps 後 for 'after / behind' and 后 (皇后 empress) as a separate character."},
  "隣": {"m":"neighbour, next-door; adjacent","on":["リン"],"kun":["となり","とな.る"],"rad":[{"c":"阝","m":"mound, hill / place (left radical, from 阜)"},{"c":"米","m":"rice"},{"c":"舛","m":"opposing feet / dance"}],"mn":"The place just over the rise (阝) — close enough to smell the rice (米) and hear the dancing feet (舛): your neighbour.","cn":"Japanese standardised on 隣 (mound 阝 on the left). Chinese uses the city radical on the right: 鄰 (traditional) → 邻 (simplified) — the same word, different radical and side."},
  "近": {"m":"near, close; recent","on":["キン"],"kun":["ちか.い"],"rad":[{"c":"辶","m":"road, movement"},{"c":"斤","m":"axe / a weight (catty)"}],"mn":"Just a short walk (辶), an axe's throw (斤) away — near, close by.","cn":""},
  "机": {"m":"desk","on":["キ"],"kun":["つくえ"],"rad":[{"c":"木","m":"wood / tree"},{"c":"几","m":"a small table / stand"}],"mn":"A slab of wood (木) on a little stand (几) — a desk.","cn":"In Chinese, 机 (jī) is the simplified form of 機 and means 'machine' (机器 jīqì); in Japanese 机 is its own kanji meaning 'desk'."},
  "銀": {"m":"silver","on":["ギン"],"kun":[],"rad":[{"c":"金","m":"metal"},{"c":"艮","m":"to stop / a limit (phonetic 'gin/gon')"}],"mn":"The metal (金) that stops just short (艮) of gold's worth — silver.","cn":""},
  "行": {"m":"to go; to carry out (conduct); a line/row","on":["コウ","ギョウ","アン"],"kun":["い.く","ゆ.く","おこな.う"],"rad":[{"c":"彳","m":"a step (left half of a road)"},{"c":"亍","m":"a step (right half of a road)"}],"mn":"A crossroads where two roads (彳 亍) meet — the place you set out to go.","cn":"Two readings split the senses: コウ = go/journey (旅行 travel), ギョウ = line/row of text (改行 line-break)."},
  "卵": {"m":"egg; spawn, roe","on":["ラン"],"kun":["たまご"],"rad":[{"c":"卵","m":"pictograph: two egg-sacs, each with a yolk dot inside"}],"mn":"Two sacs of spawn, each with a single dot of yolk — eggs.","cn":""},
  "牛": {"m":"cow, ox, cattle","on":["ギュウ"],"kun":["うし"],"rad":[{"c":"牛","m":"pictograph: an ox head with horns"}],"mn":"A horned head on a straight neck — an ox seen head-on.","cn":""},
  "乳": {"m":"milk; breast","on":["ニュウ"],"kun":["ちち","ち"],"rad":[{"c":"爫","m":"a hand reaching down"},{"c":"子","m":"child"},{"c":"乚","m":"a hook — the mother's bent form / breast"}],"mn":"A hand (爫) draws the child (子) to the breast (乚) — nursing, milk.","cn":""},
  "魚": {"m":"fish","on":["ギョ"],"kun":["うお","さかな"],"rad":[{"c":"⺈","m":"the head"},{"c":"田","m":"the scaly body"},{"c":"灬","m":"the finned tail"}],"mn":"Head (⺈), scaly body (田) and a flicking tail (灬) — a fish.","cn":"Two kun readings: さかな is the everyday word for fish, うお the older word kept in compounds (魚市場 uo-ichiba, the fish market)."},
  "肉": {"m":"meat, flesh","on":["ニク"],"kun":[],"rad":[{"c":"肉","m":"pictograph: a cut of meat with marbling lines inside"}],"mn":"A slab of meat drawn with the muscle-and-fat marbling running through it — flesh.","cn":""},
  "来": {"m":"to come; next (来年 next year)","on":["ライ"],"kun":["く.る","きた.る"],"rad":[{"c":"木","m":"a tree — originally a stalk of grain"},{"c":"从","m":"people (人人) drawn coming toward it"}],"mn":"People (从) coming toward the ripe grain (木) at harvest — to come.","cn":"The traditional/heritage form is 來; Japan and mainland China both settled on the simplified 来."},
  "帰": {"m":"to return, go home; to send back","on":["キ"],"kun":["かえ.る","かえ.す"],"rad":[{"c":"⺈","m":"a hook — the trimmed top-left of the old form"},{"c":"帚","m":"a broom (hand 彐 + cloth 巾)"}],"mn":"Take up the broom (帚), sweep the house, and head back — to return home.","cn":"Three shapes, one meaning 'return': traditional 歸, Japanese 帰, mainland-China 归."},
  "電": {"m":"electricity; (also telephone/telegram, 電話)","on":["デン"],"kun":[],"rad":[{"c":"雨","m":"rain"},{"c":"电","m":"a lightning bolt (from 申, stretching down)"}],"mn":"Lightning (电) forking down through the rain (雨) — electricity.","cn":"Mainland China simplified this to 电 (just the lightning, rain dropped); Japan keeps the full 電."},
  "車": {"m":"car, vehicle; wheel","on":["シャ"],"kun":["くるま"],"rad":[{"c":"車","m":"pictograph: a cart seen from above, the axle running through the wheels"}],"mn":"A cart from overhead: the box between two wheels, an axle through the middle — a vehicle.","cn":"Compound trap: 汽車 means 'steam train' in Japanese but 'automobile' in Chinese (汽车). China also writes the character as 车."},
  "飛": {"m":"to fly; to leap, jump","on":["ヒ"],"kun":["と.ぶ","と.ばす"],"rad":[{"c":"飛","m":"pictograph: a bird lifting off, wings and feathers flung wide"}],"mn":"Wings spread and feathers streaming as a bird leaves the ground — to fly.","cn":"Mainland China simplified this to 飞 (a single wing-stroke); Japan keeps the full winged 飛."},
  "機": {"m":"machine, mechanism; opportunity, chance; (飛行機 airplane)","on":["キ"],"kun":["はた"],"rad":[{"c":"木","m":"wood / tree"},{"c":"幾","m":"a loom of threads (幺幺) and tools — 'how many / mechanism'"}],"mn":"A wooden (木) loom (幾) with all its threads and moving parts — a machine.","cn":"Mainland China simplified 機 to 机 — the very character that means 'desk' in Japanese."},
  "自": {"m":"self, oneself; from (自〜 'starting from')","on":["ジ","シ"],"kun":["みずか.ら"],"rad":[{"c":"自","m":"pictograph: a nose"}],"mn":"A picture of a nose — and Japanese point to their own nose to mean 'me, myself'.","cn":""},
  "転": {"m":"to turn, revolve, roll over; to change/shift","on":["テン"],"kun":["ころ.がる","ころ.ぶ","ころ.がす"],"rad":[{"c":"車","m":"wheel / vehicle"},{"c":"云","m":"cloud / to say (here: rolling motion)"}],"mn":"A wheel (車) spinning round like rolling clouds (云) — to turn, to tumble.","cn":"Traditional 轉 → Japanese 転 → mainland-China 转: same 'turn', three different right sides."},
  "歩": {"m":"to walk; a step; a rate (歩合)","on":["ホ","ブ","フ"],"kun":["ある.く","あゆ.む"],"rad":[{"c":"止","m":"a footprint / foot"},{"c":"少","m":"a second, downward footprint below (it resembles 少 'small')"}],"mn":"One footprint (止), then another below it — left, right, left: to walk.","cn":"Japan writes 歩 (lower part like 少); traditional/Chinese writes 步 with one fewer stroke — same meaning."},
  "京": {"m":"capital (city)","on":["キョウ","ケイ"],"kun":[],"rad":[{"c":"京","m":"pictograph: a tall gate-tower raised on a hill"}],"mn":"A great gate-tower rising high on a mound — the seat of power, the capital.","cn":"京 = 'capital': it is the 京 in 東京 Tōkyō (east capital), 京都 Kyōto, and 北京 Beijing (north capital)."},
  "都": {"m":"metropolis, capital city; all, altogether","on":["ト","ツ"],"kun":["みやこ"],"rad":[{"c":"者","m":"person / someone (phonetic)"},{"c":"阝","m":"city / town (right-side 邑)"}],"mn":"The one city (阝) where all the people (者) gather — the great metropolis.","cn":"In Chinese, 都 (dōu) usually means 'all/both'; Japanese keeps that only in a few words (都合 tsugō) and mainly uses 都 for 'capital'."},
  "食": {"m":"to eat; food, a meal","on":["ショク","ジキ"],"kun":["た.べる","く.う"],"rad":[{"c":"𠆢","m":"a roof / lid"},{"c":"良","m":"good — here a bowl of good food"}],"mn":"Lift the lid (𠆢) off a bowl of good (良) food — time to eat.","cn":"食べる (taberu) is neutral 'eat'; 食う (kuu) is blunt and rough — casual, mostly male speech."},
  "飲": {"m":"to drink","on":["イン"],"kun":["の.む"],"rad":[{"c":"飠","m":"eat / food (left radical)"},{"c":"欠","m":"a person with mouth agape (a yawn/lack)"}],"mn":"Open your gaping mouth (欠) beside the food (飠) and gulp it down — to drink.","cn":"飲む covers more than liquids: also 'take medicine' (薬を飲む) and even swallowing smoke — in Japanese you 'drink' a tablet."},
  "見": {"m":"to see, look; to be visible; to show","on":["ケン"],"kun":["み.る","み.える","み.せる"],"rad":[{"c":"目","m":"eye"},{"c":"儿","m":"human legs"}],"mn":"A big eye (目) up on walking legs (儿) — a person going about, looking: to see.","cn":"Mainland China simplifies this to 见; Japan keeps the full 見."},
  "聞": {"m":"to hear, listen; to ask; (news, 新聞)","on":["ブン","モン"],"kun":["き.く","き.こえる"],"rad":[{"c":"門","m":"gate"},{"c":"耳","m":"ear"}],"mn":"Press an ear (耳) to the gate (門) to catch what's on the other side — to listen.","cn":"Mainland China simplifies the gate 門→门, writing 闻; Japan keeps 聞."},
  "読": {"m":"to read","on":["ドク","トク","トウ"],"kun":["よ.む"],"rad":[{"c":"言","m":"words / to speak"},{"c":"売","m":"to sell (phonetic; was 賣 in the old form)"}],"mn":"Speak the words (言) aloud as if crying them out to sell (売) — to read out.","cn":"Traditional 讀 (言+賣) → Japanese 読 (言+売) → mainland-China 读 (讠+卖): each trimmed the right side differently."},
  "書": {"m":"to write; writing; a book, document","on":["ショ"],"kun":["か.く"],"rad":[{"c":"聿","m":"a hand gripping a writing brush"},{"c":"曰","m":"to say / a tablet or page"}],"mn":"A hand holding a brush (聿) moving across the page (曰) — to write.","cn":"Mainland China simplifies this to 书 (barely recognizable); Japan and Taiwan keep 書."},
  "買": {"m":"buy, purchase","on":["バイ"],"kun":["か.う"],"rad":[{"c":"罒","m":"net (eye laid flat)"},{"c":"貝","m":"shell / money"}],"mn":"Cast a net (罒) over a pile of shell-money (貝) and haul it in — you buy.","cn":"Japanese keeps the traditional shape 買 (net 罒 over shell 貝); simplified Chinese writes it 买."},
  "話": {"m":"talk, speak; story, conversation","on":["ワ"],"kun":["はな.す","はなし"],"rad":[{"c":"言","m":"words / speech"},{"c":"舌","m":"tongue"}],"mn":"Words (言) rolling off the tongue (舌) — you talk and tell a story.","cn":"Simplified Chinese writes this 话 (讠 for the word radical 言); Japanese keeps the full 言."},
  "勉": {"m":"exertion, diligence, effort","on":["ベン"],"kun":[],"rad":[{"c":"免","m":"escape / exemption"},{"c":"力","m":"power, strength"}],"mn":"Pour strength (力) into escaping (免) ignorance — that hard grind is diligence.","cn":"勉強 (べんきょう) means 'study' in Japanese, but Chinese 勉强 (miǎnqiǎng) means 'to force / reluctantly'."},
  "強": {"m":"strong, strength; force","on":["キョウ","ゴウ"],"kun":["つよ.い","つよ.まる","つよ.める","し.いる"],"rad":[{"c":"弓","m":"bow"},{"c":"厶","m":"private / wrapping"},{"c":"虫","m":"insect, bug"}],"mn":"A drawn bow (弓) and a tough armored beetle (虫) — both mean strong.","cn":""},
  "音": {"m":"sound, noise; tone","on":["オン","イン"],"kun":["おと","ね"],"rad":[{"c":"立","m":"stand"},{"c":"日","m":"sun / say"}],"mn":"Stand up (立) and let a note ring from your mouth (日) — a sound rises.","cn":""},
  "楽": {"m":"music; comfort, ease, pleasure","on":["ガク","ラク"],"kun":["たの.しい","たの.しむ"],"rad":[{"c":"白","m":"white (a drum head)"},{"c":"木","m":"tree / wooden stand"}],"mn":"A white drum (白) on a wooden stand (木) — music (ガク) that brings pleasure (ラク).","cn":"Three forms of one character: traditional 樂, Japanese shinjitai 楽, simplified Chinese 乐."},
  "映": {"m":"reflect; project (a film); shine","on":["エイ"],"kun":["うつ.る","うつ.す","は.える"],"rad":[{"c":"日","m":"sun"},{"c":"央","m":"center"}],"mn":"The sun (日) strikes dead center (央) — light reflects and an image is projected.","cn":"映画 (えいが) = 'movie' in Japanese; Chinese says 电影 (diànyǐng)."},
  "画": {"m":"picture, drawing; stroke (of a character)","on":["ガ","カク"],"kun":[],"rad":[{"c":"一","m":"one / a drawn line"},{"c":"田","m":"field"},{"c":"凵","m":"open box / frame"}],"mn":"Draw a boundary line (一) around a framed field (田 in 凵) — a picture, or a brush stroke.","cn":""},
  "手": {"m":"hand","on":["シュ"],"kun":["て","た"],"rad":[{"c":"手","m":"an open hand with fingers and wrist"}],"mn":"A pictograph of a hand — fingers splayed above the wrist.","cn":""},
  "紙": {"m":"paper","on":["シ"],"kun":["かみ"],"rad":[{"c":"糸","m":"thread / silk"},{"c":"氏","m":"clan, family"}],"mn":"The papermaker clan (氏) mats wet fibers (糸) into a flat sheet — paper.","cn":"手紙 means 'letter' in Japanese — but the same characters 手紙 (shǒuzhǐ) mean 'toilet paper' in Chinese."},
  "新": {"m":"new","on":["シン"],"kun":["あたら.しい","あら.た","にい"],"rad":[{"c":"立","m":"stand"},{"c":"木","m":"tree"},{"c":"斤","m":"axe"}],"mn":"Take an axe (斤) to a standing (立) tree (木) — the freshly cut wood is new.","cn":""},
  "図": {"m":"diagram, drawing, plan; map","on":["ズ","ト"],"kun":["はか.る"],"rad":[{"c":"囗","m":"enclosure / border"},{"c":"メ","m":"scribbled plan lines (looks like katakana メ)"}],"mn":"Inside a border (囗) you scratch out crossing lines (メ) — a diagram or a map.","cn":"Three forms of one character: traditional 圖, Japanese shinjitai 図, simplified Chinese 图."},
  "館": {"m":"large building, hall, public building","on":["カン"],"kun":["やかた"],"rad":[{"c":"食","m":"eat / food"},{"c":"官","m":"official, government post"}],"mn":"A grand place where officials (官) are fed (食) — a hall, an embassy, a public building.","cn":""},
  "喫": {"m":"consume — eat, drink, smoke","on":["キツ"],"kun":[],"rad":[{"c":"口","m":"mouth"},{"c":"契","m":"pledge, contract"}],"mn":"The mouth (口) seals a pledge (契) with tea or smoke — to consume it.","cn":"In Japanese 喫 lives in 喫茶店 (kissaten, 'café') and 喫煙 ('smoking'); modern Chinese writes 'eat' as 吃 (chī)."},
  "飯": {"m":"cooked rice; meal","on":["ハン"],"kun":["めし"],"rad":[{"c":"食","m":"eat / food"},{"c":"反","m":"anti, turn over (phonetic)"}],"mn":"Food (食) you return to (反) morning, noon and night — a bowl of cooked rice.","cn":"Simplified Chinese shrinks the food radical 飠→饣, giving 饭; Japanese keeps 飯. ご飯 = rice / a meal."},
  "朝": {"m":"morning; dynasty, court","on":["チョウ"],"kun":["あさ"],"rad":[{"c":"日","m":"sun"},{"c":"十","m":"sprouting grass / reeds (doubled around the sun)"},{"c":"月","m":"moon"}],"mn":"The sun (日) climbs through the reeds (十) while the moon (月) still lingers — morning.","cn":""},
  "晩": {"m":"evening, night; late","on":["バン"],"kun":[],"rad":[{"c":"日","m":"sun"},{"c":"免","m":"escape, get away"}],"mn":"The sun (日) escapes (免) below the horizon — evening comes.","cn":""},
  "昨": {"m":"previous; yesterday","on":["サク"],"kun":[],"rad":[{"c":"日","m":"sun / day"},{"c":"乍","m":"suddenly, just made"}],"mn":"The day (日) just made (乍) and already gone by — yesterday.","cn":""},
  "週": {"m":"week","on":["シュウ"],"kun":[],"rad":[{"c":"辶","m":"movement, road"},{"c":"周","m":"circuit, full lap"}],"mn":"Travel (辶) one full lap (周) of days — that circuit is a week.","cn":"Japanese uses 週 for 'week'; Chinese usually writes 周 (the same phonetic without 辶)."},
  "末": {"m":"end, tip, close; powder","on":["マツ","バツ"],"kun":["すえ"],"rad":[{"c":"木","m":"tree"},{"c":"一","m":"long mark at the top"}],"mn":"A long stroke marks the very top of a tree (木) — its tip, the far end.","cn":"Don't confuse with 未 ('not yet'): in 末 the TOP stroke is longer (the tip/end); in 未 it's shorter."},
  "夜": {"m":"night, evening","on":["ヤ"],"kun":["よる","よ"],"rad":[{"c":"亠","m":"lid, roof"},{"c":"亻","m":"person"},{"c":"夕","m":"evening moon"}],"mn":"A person (亻) under a roof (亠) with the evening moon (夕) outside — night.","cn":""},
  "物": {"m":"thing, object; matter","on":["ブツ","モツ"],"kun":["もの"],"rad":[{"c":"牛","m":"cow, ox"},{"c":"勿","m":"must not / fluttering banner"}],"mn":"An ox (牛) beside a fluttering banner (勿) — a stand-in for things of every kind.","cn":""},
  "仕": {"m":"serve; do, work","on":["シ","ジ"],"kun":["つか.える"],"rad":[{"c":"亻","m":"person"},{"c":"士","m":"samurai, scholar, gentleman"}],"mn":"A person (亻) attending a lord like a samurai (士) — to serve, to work.","cn":"仕事 (しごと, 'work / job') is a native Japanese compound; Chinese says 工作, not 仕事."},
  "事": {"m":"matter, affair, thing; job","on":["ジ","ズ"],"kun":["こと"],"rad":[{"c":"口","m":"mouth / recorded words"},{"c":"彐","m":"hand"},{"c":"亅","m":"brush-stake it holds"}],"mn":"A hand (彐) grips a brush-stake (亅) to record spoken business (口) — matters, affairs.","cn":""},
  "休": {"m":"rest","on":["キュウ"],"kun":["やす.む","やす.まる","やす.める"],"rad":[{"c":"亻","m":"person"},{"c":"木","m":"tree"}],"mn":"A person (亻) leaning against a tree (木) — stopping to rest.","cn":""},
  "少": {"m":"few, little; a small amount","on":["ショウ"],"kun":["すく.ない","すこ.し"],"rad":[{"c":"小","m":"small"},{"c":"丿","m":"a slash / stroke shaved off"}],"mn":"Take 'small' (小) and shave one more stroke off it (丿) — even less, so 'few, a little.'","cn":""},
  "全": {"m":"whole, entire, all; complete","on":["ゼン"],"kun":["まった.く","すべ.て"],"rad":[{"c":"入","m":"enter / roof over"},{"c":"王","m":"king / jade (玉)"}],"mn":"Flawless jade (王) gathered under one roof (入) — nothing missing, so 'whole, complete.'","cn":""},
  "然": {"m":"so, thus; -like (suffix, e.g. 自然, 全然)","on":["ゼン","ネン"],"kun":[],"rad":[{"c":"月","m":"meat (肉)"},{"c":"犬","m":"dog"},{"c":"灬","m":"fire"}],"mn":"Dog (犬) meat (月) roasting over a fire (灬) — 'to burn'; borrowed for 'so, thus,' while 燃 took over 'burn.'","cn":""},
  "毎": {"m":"every, each","on":["マイ"],"kun":["ごと"],"rad":[{"c":"𠂉","m":"a hairpin / person on top"},{"c":"母","m":"mother"}],"mn":"A mother (母) tends every single child, day after day — 'every, each.'","cn":""},
  "酒": {"m":"alcohol, sake, liquor","on":["シュ"],"kun":["さけ","さか"],"rad":[{"c":"氵","m":"water / liquid"},{"c":"酉","m":"wine jar"}],"mn":"Liquid (氵) fermenting inside a wine jar (酉) — alcohol, sake.","cn":""},
  "高": {"m":"tall, high; expensive","on":["コウ"],"kun":["たか.い","たか.まる","たか.める"],"rad":[{"c":"高","m":"pictograph of a tall, multi-storied tower"}],"mn":"A picture of a tall watchtower rising over a gate — 'high, tall'; and high-value things are 'expensive.'","cn":""},
  "安": {"m":"cheap; safe, peaceful, at ease","on":["アン"],"kun":["やす.い","やす.らか"],"rad":[{"c":"宀","m":"roof"},{"c":"女","m":"woman"}],"mn":"A woman (女) resting safe under a roof (宀) — peace and ease; what's easy to get is 'cheap.'","cn":"In Japanese 安い means 'cheap.' In Chinese 安 (ān) means only 'safe / peaceful' — 'cheap' is 便宜 (piányi)."},
  "大": {"m":"big, large, great","on":["ダイ","タイ"],"kun":["おお.きい","おお","おお.いに"],"rad":[{"c":"大","m":"a person standing with arms flung wide"}],"mn":"A person stretching both arms out as wide as they can go — 'big, great.'","cn":""},
  "小": {"m":"small, little","on":["ショウ"],"kun":["ちい.さい","こ","お"],"rad":[{"c":"小","m":"three tiny strokes / something split into bits"}],"mn":"A center line with two little splinters flaking off either side — a small, small thing.","cn":""},
  "古": {"m":"old (of things), ancient","on":["コ"],"kun":["ふる.い","ふる.す"],"rad":[{"c":"十","m":"ten"},{"c":"口","m":"mouth"}],"mn":"A tale passed mouth (口) to mouth across ten (十) generations — that makes it 'old.'","cn":""},
  "面": {"m":"face, surface; mask; aspect","on":["メン"],"kun":["おも","おもて","つら"],"rad":[{"c":"一","m":"the outline / brow of a face"},{"c":"目","m":"eye"}],"mn":"The outline of a head with one eye (目) framed inside — a 'face,' and by extension any 'surface.'","cn":""},
  "難": {"m":"difficult, hard; disaster","on":["ナン"],"kun":["むずか.しい","かた.い"],"rad":[{"c":"𦰩","m":"phonetic element (shared with 漢, 嘆)"},{"c":"隹","m":"short-tailed bird"}],"mn":"Pinning down this short-tailed bird (隹) is 'hard' — difficult, and a hardship is a disaster.","cn":""},
  "速": {"m":"fast, quick, prompt; speed","on":["ソク"],"kun":["はや.い","はや.める","すみ.やか"],"rad":[{"c":"辶","m":"movement / road"},{"c":"束","m":"bundle"}],"mn":"A tied bundle (束) rushed down the road (辶) — moving 'fast,' at speed.","cn":""},
  "静": {"m":"quiet, calm, still","on":["セイ","ジョウ"],"kun":["しず.か","しず.まる","しず.める"],"rad":[{"c":"青","m":"blue-green / fresh"},{"c":"争","m":"contend, struggle"}],"mn":"When the struggle (争) settles into cool, fresh blue (青) — everything goes 'quiet, still.'","cn":""},
  "有": {"m":"to exist, to have, to possess","on":["ユウ","ウ"],"kun":["あ.る"],"rad":[{"c":"𠂇","m":"hand"},{"c":"月","m":"meat (肉)"}],"mn":"A hand (𠂇) gripping a slab of meat (月) — you 'have' it, it 'exists' in your grasp.","cn":""},
  "便": {"m":"convenient; mail/transport service; bodily waste","on":["ベン","ビン"],"kun":["たよ.り"],"rad":[{"c":"亻","m":"person"},{"c":"更","m":"renew, change"}],"mn":"A person (亻) who reworks (更) things to make them handy — 'convenient.'","cn":"Two readings split the meanings: ビン = a mail/transport run (郵便 mail, a flight 便); ベン = convenience or bodily waste (便利 convenient, 大便 feces)."},
  "利": {"m":"advantage, profit, benefit; sharp","on":["リ"],"kun":["き.く"],"rad":[{"c":"禾","m":"grain / rice plant"},{"c":"刂","m":"knife (刀)"}],"mn":"A knife (刂) keen enough to reap the grain (禾) — 'sharp,' and a good harvest is 'profit.'","cn":""},
  "元": {"m":"origin, source, base; former, the beginning","on":["ゲン","ガン"],"kun":["もと"],"rad":[{"c":"二","m":"the top (head lines)"},{"c":"儿","m":"human legs"}],"mn":"A person (儿) with the very top (二) marked — the head, the start, the 'origin.'","cn":"In China 元 (yuán) is the unit of currency; Japan writes its yen as 円 and uses 元 only for 'origin / former' (元気, 手元)."},
  "気": {"m":"spirit, energy, mind, mood; air, vapor","on":["キ","ケ"],"kun":[],"rad":[{"c":"气","m":"rising vapor / breath"},{"c":"メ","m":"cross-shape, reduced from 米 (rice)"}],"mn":"Steam (气) curling up off cooking rice (メ, from 米) — breath, air, and the vital energy of the 'spirit.'","cn":"Japanese 気 keeps メ inside; traditional Chinese is 氣 (with 米 rice), and simplified Chinese is 气 (empty inside)."},
  "簡": {"m":"simple, brief, concise; (old) writing tablet","on":["カン"],"kun":[],"rad":[{"c":"竹","m":"bamboo"},{"c":"間","m":"interval (門 gate + 日 sun)"}],"mn":"Thin bamboo (竹) strips spaced at intervals (間) were the old writing slips — jot it 'brief and simple.'","cn":""},
  "単": {"m":"single, mono-, simple","on":["タン"],"kun":[],"rad":[{"c":"丷","m":"two prongs / horns"},{"c":"田","m":"framed body (looks like 'field')"},{"c":"十","m":"the shaft"}],"mn":"Two prongs (丷) on a framed shaft (田+十) form one forked weapon — a 'single' tool; hence single, simple.","cn":""},
  "変": {"m":"to change; strange, odd","on":["ヘン"],"kun":["か.わる","か.える"],"rad":[{"c":"亦","m":"top element"},{"c":"夂","m":"a foot in motion"}],"mn":"A foot in motion (夂) never holds still — it keeps 'changing'; and what has changed can look 'strange.'","cn":"Japanese 変 is the simplified shape of traditional 變 (still used in Chinese)."},
  "親": {"m":"parent; intimacy, closeness; personally","on":["シン"],"kun":["おや","した.しい","した.しむ"],"rad":[{"c":"立","m":"stand"},{"c":"木","m":"tree"},{"c":"見","m":"see, watch"}],"mn":"Standing (立) up a tree (木) to watch (見) over the children below — that's a 'parent,' close and caring.","cn":""},
  "切": {"m":"to cut; earnest, keen, urgent","on":["セツ","サイ"],"kun":["き.る","き.れる"],"rad":[{"c":"七","m":"seven"},{"c":"刀","m":"knife / sword"}],"mn":"A knife (刀) slicing clean through seven (七) — 'to cut'; cutting close to the bone means 'earnest.'","cn":""},
  "暇": {"m":"free time, leisure, spare time","on":["カ"],"kun":["ひま","いとま"],"rad":[{"c":"日","m":"sun / day"},{"c":"叚","m":"phonetic 'borrow' (as in 仮, 借)"}],"mn":"A day (日) you borrow (叚) back for yourself — 'free time, leisure.'","cn":""},
  "賑": {"m":"bustling, lively, crowded; prosperous","on":["シン"],"kun":["にぎ.わう","にぎ.やか"],"rad":[{"c":"貝","m":"shell / money"},{"c":"辰","m":"dragon (5th zodiac) / shellfish"}],"mn":"Money (貝) flowing like a rising dragon (辰) — a bustling, thriving marketplace.","cn":"Chinese 賑 (zhèn, simplified 赈) means to relieve/aid the needy (disaster relief); Japanese 賑 instead means lively, bustling, crowded (賑やか)."},
  "町": {"m":"town; town district","on":["チョウ"],"kun":["まち"],"rad":[{"c":"田","m":"rice field"},{"c":"丁","m":"street block / nail"}],"mn":"Rice fields (田) laid out in blocks along a street (丁) — a town.","cn":"町 is an everyday Japanese word for town / city district; in Chinese it is a rare character (a raised path between fields), seldom used."},
  "方": {"m":"direction, way; method; (polite) person","on":["ホウ"],"kun":["かた"],"rad":[{"c":"方","m":"a plow / signpost (pictograph)"}],"mn":"A plow blade cutting a straight furrow — it points the way: direction, side, method.","cn":""},
  "一": {"m":"one","on":["イチ","イツ"],"kun":["ひと","ひと.つ"],"rad":[{"c":"一","m":"a single horizontal stroke"}],"mn":"A single horizontal stroke — one.","cn":""},
  "番": {"m":"number (in a series); one's turn; guard, watch","on":["バン"],"kun":[],"rad":[{"c":"釆","m":"animal paw-print / to sort"},{"c":"田","m":"rice field"}],"mn":"Reading animal tracks (釆) across a field (田) — you take turns on watch, keeping the count.","cn":""},
  "天": {"m":"heaven, sky","on":["テン"],"kun":["あま","あめ"],"rad":[{"c":"大","m":"a big person, arms out"},{"c":"一","m":"the line of the sky above"}],"mn":"A big person (大) with a line stretched above their head (一) — the sky, heaven.","cn":""},
  "夏": {"m":"summer","on":["カ","ゲ"],"kun":["なつ"],"rad":[{"c":"自","m":"face / head"},{"c":"夂","m":"trailing legs / walking"}],"mn":"A dancer with head held high (自) striding on trailing feet (夂) — the lively figure of summer.","cn":"In Chinese 夏 also names the ancient Xia dynasty and, in 華夏 (Huáxià), stands for China itself; Japanese uses it just for 'summer'."},
  "冬": {"m":"winter","on":["トウ"],"kun":["ふゆ"],"rad":[{"c":"夂","m":"trailing legs / the end"},{"c":"冫","m":"ice (two drops)"}],"mn":"Trailing legs (夂) at the year's end, with two drops of ice (冫) below — winter.","cn":""},
  "春": {"m":"spring","on":["シュン"],"kun":["はる"],"rad":[{"c":"艸","m":"sprouting plants (fused in the top)"},{"c":"日","m":"sun"}],"mn":"Plants sprouting (艸) up toward the warming sun (日) — spring.","cn":""},
  "秋": {"m":"autumn, fall","on":["シュウ"],"kun":["あき"],"rad":[{"c":"禾","m":"grain / rice plant"},{"c":"火","m":"fire"}],"mn":"Grain (禾) turning fire-red (火) in the fields — harvest time, autumn.","cn":""},
  "暑": {"m":"hot (of weather)","on":["ショ"],"kun":["あつ.い"],"rad":[{"c":"日","m":"sun"},{"c":"者","m":"person / someone"}],"mn":"The sun (日) bearing down on a person (者) — hot, sweltering weather.","cn":""},
  "寒": {"m":"cold (of weather)","on":["カン"],"kun":["さむ.い"],"rad":[{"c":"宀","m":"roof"},{"c":"人","m":"person"},{"c":"冫","m":"ice"}],"mn":"A person (人) huddled under a roof (宀) with ice (冫) at their feet — freezing cold.","cn":""},
  "好": {"m":"to like, be fond of; good, favorable","on":["コウ"],"kun":["す.き","この.む"],"rad":[{"c":"女","m":"woman"},{"c":"子","m":"child"}],"mn":"A woman (女) cradling her child (子) — the picture of fondness: to like.","cn":"In Chinese 好 (hǎo) is the everyday word for 'good' and the greeting 你好; Japanese 好 mainly means 'to like / be fond of', not 'good' on its own."},
  "嫌": {"m":"to dislike, hate; disagreeable","on":["ケン","ゲン"],"kun":["きら.う","いや"],"rad":[{"c":"女","m":"woman"},{"c":"兼","m":"combine / all at once"}],"mn":"A woman (女) burdened with too much at once (兼) grows to dislike it — hate, distaste.","cn":""},
  "分": {"m":"part, portion; minute; to divide; to understand","on":["ブン","フン","ブ"],"kun":["わ.ける","わ.かる","わ.かれる"],"rad":[{"c":"八","m":"split apart (eight)"},{"c":"刀","m":"knife / sword"}],"mn":"A knife (刀) cutting something apart into two (八) — to divide; a part, a minute.","cn":""},
  "歌": {"m":"song; to sing","on":["カ"],"kun":["うた","うた.う"],"rad":[{"c":"哥","m":"song (doubled 可)"},{"c":"欠","m":"open mouth / yawn"}],"mn":"Open your mouth wide (欠) and pour out song after song (哥) — to sing.","cn":""},
  "料": {"m":"materials, ingredients; fee, charge","on":["リョウ"],"kun":[],"rad":[{"c":"米","m":"rice"},{"c":"斗","m":"dipper / measure"}],"mn":"Measuring out rice (米) with a dipper (斗) — ingredients, materials, a set fee.","cn":""},
  "理": {"m":"reason, logic; principle; to manage","on":["リ"],"kun":[],"rad":[{"c":"王","m":"jade (王 = 玉)"},{"c":"里","m":"village"}],"mn":"Polishing jade (王) along its natural veins, like the ordered paths of a village (里) — the underlying reason.","cn":""},
  "冒": {"m":"to risk, brave, dare; to face (danger)","on":["ボウ"],"kun":["おか.す"],"rad":[{"c":"冃","m":"cloth cover / helmet (looks like 日)"},{"c":"目","m":"eye"}],"mn":"Pulling a cover (冃, not 日!) down over your eyes (目) and pushing ahead blindly — to risk, to brave.","cn":""},
  "険": {"m":"steep; dangerous, precipitous","on":["ケン"],"kun":["けわ.しい"],"rad":[{"c":"阝","m":"hill / mound (left)"},{"c":"僉","m":"all together (phonetic)"}],"mn":"A hillside (阝) so sheer that everyone together (僉) dreads it — steep, dangerous.","cn":"Japanese simplified 險 to 険; mainland China simplified the same character to 险 — same meaning (danger, steep), different modern shapes."},
  "待": {"m":"to wait; to await, expect","on":["タイ"],"kun":["ま.つ"],"rad":[{"c":"彳","m":"step / go"},{"c":"寺","m":"temple"}],"mn":"Stepping (彳) up to the temple (寺) — then waiting patiently for your turn.","cn":""},
  "立": {"m":"to stand; to stand up, set up","on":["リツ","リュウ"],"kun":["た.つ","た.てる"],"rad":[{"c":"大","m":"a standing person"},{"c":"一","m":"the ground"}],"mn":"A person (大) planted firmly on the ground line (一) — to stand.","cn":""},
  "座": {"m":"to sit; seat, gathering","on":["ザ"],"kun":["すわ.る"],"rad":[{"c":"广","m":"roof / lean-to"},{"c":"人","m":"person (×2)"},{"c":"土","m":"earth / ground"}],"mn":"Two people (人人) settled on the earth (土) under a roof (广) — to sit; a seat.","cn":""},
  "遊": {"m":"to play; to enjoy oneself, roam","on":["ユウ"],"kun":["あそ.ぶ"],"rad":[{"c":"辶","m":"movement / road"},{"c":"方","m":"fluttering banner"},{"c":"子","m":"child"}],"mn":"A child (子) roaming the roads (辶) with a fluttering banner (方) — out to play.","cn":""},
  "泳": {"m":"to swim","on":["エイ"],"kun":["およ.ぐ"],"rad":[{"c":"氵","m":"water"},{"c":"永","m":"eternity / a long time"}],"mn":"Stroking through water (氵) for a long, long stretch (永) — to swim.","cn":""},
  "伝": {"m":"convey, transmit; legend, tradition","on":["デン"],"kun":["つた.わる","つた.える","つた.う"],"rad":[{"c":"亻","m":"person"},{"c":"云","m":"say / cloud"}],"mn":"A person (亻) passing on what was said (云) — to convey, transmit, and so a legend that gets handed down.","cn":"Japanese shinjitai 伝; the traditional/Chinese form is 傳 (chuán). Same meaning (transmit, pass on)."},
  "開": {"m":"open","on":["カイ"],"kun":["ひら.く","ひら.ける","あ.く","あ.ける"],"rad":[{"c":"門","m":"gate"},{"c":"开","m":"two hands lifting the bar"}],"mn":"Two hands (开) lift the bolt off a gate (門) — to open.","cn":"PRC simplified drops the gate to write 开 (kāi); Japanese keeps the full 開. Meaning 'open' is shared."},
  "閉": {"m":"close, shut","on":["ヘイ"],"kun":["と.じる","と.ざす","し.まる","し.める"],"rad":[{"c":"門","m":"gate"},{"c":"才","m":"bar / bolt across"}],"mn":"A bar (才) dropped across the gate (門) — to close, shut.","cn":"PRC simplified is 闭 (with the simplified gate 门); Japanese keeps 閉. Meaning 'close/shut' is shared."},
  "使": {"m":"use, employ; envoy, messenger","on":["シ"],"kun":["つか.う"],"rad":[{"c":"亻","m":"person"},{"c":"吏","m":"official, clerk"}],"mn":"A person (亻) sends an official (吏) off on an errand — to use, employ, dispatch a messenger.","cn":""},
  "作": {"m":"make, produce, create","on":["サク","サ"],"kun":["つく.る"],"rad":[{"c":"亻","m":"person"},{"c":"乍","m":"make / suddenly"}],"mn":"A person (亻) suddenly setting to work (乍) — to make, produce, create.","cn":""},
  "窓": {"m":"window","on":["ソウ"],"kun":["まど"],"rad":[{"c":"穴","m":"hole, cave"},{"c":"厶","m":"private, self"},{"c":"心","m":"heart"}],"mn":"A hole (穴) in the wall your private heart (厶心) gazes through — a window.","cn":"The standard Chinese form for 'window' is 窗 (chuāng); 窓 is a variant that Japan adopted as standard."},
  "度": {"m":"degree; time, occasion; extent","on":["ド","ト","タク"],"kun":["たび"],"rad":[{"c":"广","m":"roof, lean-to"},{"c":"廿","m":"twenty (a measure)"},{"c":"又","m":"hand"}],"mn":"Under a roof (广) a hand (又) measures out degrees, one time (たび) at a time.","cn":""},
  "写": {"m":"copy; photograph; describe","on":["シャ"],"kun":["うつ.す","うつ.る"],"rad":[{"c":"冖","m":"cover"},{"c":"与","m":"give, bestow"}],"mn":"Under a cover (冖) you give back (与) an exact likeness — to copy, to photograph.","cn":"In Chinese, 写 (xiě) means 'to write'. Japanese narrowed it to 'copy / photograph' (写真 = photo) and writes 'write' as 書."},
  "真": {"m":"true, real; genuine","on":["シン"],"kun":["ま"],"rad":[{"c":"十","m":"ten"},{"c":"目","m":"eye"},{"c":"八","m":"legs / base"}],"mn":"Ten (十) eyes (目) inspecting from every side confirm it — it's true, real.","cn":""},
  "撮": {"m":"take (a photo); pick up, pinch","on":["サツ"],"kun":["と.る"],"rad":[{"c":"扌","m":"hand"},{"c":"最","m":"most, utmost"}],"mn":"Your hand (扌) grabs the most (最) fleeting moment — to take a photo, to pinch up.","cn":"In Chinese 撮 (cuō) mainly means 'to gather / a pinch'; Japanese specialized it to 'take a photo' (撮影). Chinese photography is 摄影."},
  "言": {"m":"say, speak; word, speech","on":["ゲン","ゴン"],"kun":["い.う","こと"],"rad":[{"c":"口","m":"mouth"},{"c":"亠","m":"rising lines = sound / tongue"}],"mn":"Lines of sound rising from a mouth (口) — to say, to speak; words.","cn":""},
  "消": {"m":"extinguish, put out; erase; disappear","on":["ショウ"],"kun":["き.える","け.す"],"rad":[{"c":"氵","m":"water"},{"c":"肖","m":"dwindle / resemble"}],"mn":"Water (氵) wears a thing down to nothing (肖) until it vanishes — to extinguish, erase.","cn":""},
  "住": {"m":"live, reside, dwell","on":["ジュウ"],"kun":["す.む","す.まう"],"rad":[{"c":"亻","m":"person"},{"c":"主","m":"master, main"}],"mn":"The person (亻) who is master (主) of the house lives there — to reside, dwell.","cn":""},
  "知": {"m":"know; wisdom","on":["チ"],"kun":["し.る"],"rad":[{"c":"矢","m":"arrow"},{"c":"口","m":"mouth"}],"mn":"Words from the mouth (口) that fly straight and sure as an arrow (矢) — to know.","cn":""},
  "持": {"m":"hold, have, carry","on":["ジ"],"kun":["も.つ"],"rad":[{"c":"扌","m":"hand"},{"c":"寺","m":"temple"}],"mn":"A hand (扌) that grips as steady and lasting as a temple (寺) — to hold, carry, have.","cn":""},
  "働": {"m":"work, labor","on":["ドウ"],"kun":["はたら.く"],"rad":[{"c":"亻","m":"person"},{"c":"動","m":"move, motion"}],"mn":"A person (亻) in motion (動) — to work, to labor.","cn":"国字 — a kanji invented in Japan (亻 'person' + 動 'move'). Classical Chinese has no such character; Chinese writes 'work/labor' as 工作 / 劳动."},
  "雨": {"m":"rain","on":["ウ"],"kun":["あめ","あま"],"rad":[{"c":"雨","m":"raindrops falling from a cloud (pictograph)"}],"mn":"Four drops falling from a cloud drawn across the sky — rain.","cn":""},
  "雪": {"m":"snow","on":["セツ"],"kun":["ゆき"],"rad":[{"c":"雨","m":"rain"},{"c":"彐","m":"hand / broom"}],"mn":"The rain (雨) that falls so soft you can sweep it with a broom (彐) — snow.","cn":""},
  "降": {"m":"fall (rain/snow); descend, get off","on":["コウ"],"kun":["ふ.る","お.りる","お.ろす"],"rad":[{"c":"阝","m":"hill, mound"},{"c":"夅","m":"feet coming down"}],"mn":"Feet stepping down (夅) a hill (阝) — to descend, get off; rain to come down.","cn":""},
  "会": {"m":"meet; meeting, association","on":["カイ","エ"],"kun":["あ.う"],"rad":[{"c":"人","m":"person (gathering)"},{"c":"云","m":"cloud / say"}],"mn":"People (人) gathering together under one roof — to meet; a meeting, an association.","cn":"Japanese shinjitai 会 (also PRC simplified); the traditional form is 會 (huì), still used in Taiwan and Hong Kong. Meaning shared."},
  "社": {"m":"company; shrine; society","on":["シャ"],"kun":["やしろ"],"rad":[{"c":"礻","m":"altar, ritual / spirit"},{"c":"土","m":"earth, ground"}],"mn":"An altar (礻) set on the earth (土) where people gather — a shrine, and so a company or society.","cn":"In Chinese 社 (shè) means society / agency (社会, 报社). Japanese also uses it for a Shinto shrine (神社, kun やしろ), a sense Chinese lacks; the 'company/society' meaning (会社) is shared."},
  "入": {"m":"enter, go in; put in","on":["ニュウ"],"kun":["い.る","はい.る","い.れる"],"rad":[{"c":"入","m":"lines converging inward through a doorway (pictograph)"}],"mn":"Two strokes leaning in through an opening — to enter, to put in.","cn":""},
  "出": {"m":"go out, exit; put out, take out","on":["シュツ","スイ"],"kun":["で.る","だ.す"],"rad":[{"c":"出","m":"a sprout pushing up out of the ground (pictograph)"}],"mn":"A shoot breaking up and out of the earth, growth upon growth — to go out, to put out.","cn":""},
  "触": {"m":"touch, feel; contact","on":["ショク"],"kun":["ふ.れる","さわ.る"],"rad":[{"c":"角","m":"horn"},{"c":"虫","m":"insect, bug"}],"mn":"An insect (虫) probing the world with its horn (角) — to touch, to feel, to make contact.","cn":"Japanese shinjitai 触 (also PRC simplified); the traditional form is 觸 (chù). Same meaning (touch, contact)."},
  "脱": {"m":"take off, remove; escape, shed","on":["ダツ"],"kun":["ぬ.ぐ","ぬ.げる"],"rad":[{"c":"月","m":"flesh, body"},{"c":"兌","m":"shed / exchange"}],"mn":"Sloughing something off (兌) the body (月) — to take off, remove, shed, escape.","cn":""},
  "靴": {"m":"shoes, footwear","on":["カ"],"kun":["くつ"],"rad":[{"c":"革","m":"leather / hide"},{"c":"化","m":"change, transform"}],"mn":"Leather (革) shaped and transformed (化) to fit your feet — shoes (靴).","cn":"In Chinese 靴 (xuē) means specifically boots; everyday shoes are 鞋 (xié). Japanese 靴 covers all footwear."},
  "博": {"m":"broad, extensive; doctorate (博士); gambling","on":["ハク","バク"],"kun":[],"rad":[{"c":"十","m":"ten / many"},{"c":"甫","m":"wide field, begin"},{"c":"寸","m":"hand, measure"}],"mn":"Ten (十) wide fields (甫) measured by hand (寸) — vast, broad knowledge, the mark of a scholar (博士).","cn":""},
  "神": {"m":"god, deity; spirit; divine","on":["シン","ジン"],"kun":["かみ","かん","こう"],"rad":[{"c":"礻","m":"altar / spirit (示)"},{"c":"申","m":"lightning; to say"}],"mn":"At the altar (礻) where lightning (申) strikes down from the sky — the presence of a god (神).","cn":""},
  "吸": {"m":"suck, inhale, absorb","on":["キュウ"],"kun":["す.う"],"rad":[{"c":"口","m":"mouth"},{"c":"及","m":"reach, extend to"}],"mn":"The mouth (口) reaches out (及) to draw the air in — to inhale, to suck (吸う).","cn":""},
  "漫": {"m":"cartoon (漫画); rambling, aimless, random","on":["マン"],"kun":[],"rad":[{"c":"氵","m":"water"},{"c":"曼","m":"long, drawn-out"}],"mn":"Water (氵) spreading long and loose (曼) with no aim — rambling lines that became the comic (漫画).","cn":""},
  "緒": {"m":"cord, strap, thread; beginning","on":["ショ","チョ"],"kun":["お"],"rad":[{"c":"糸","m":"thread, silk"},{"c":"者","m":"person"}],"mn":"The silk cord (糸) a person (者) grips and pulls — the loose end (緒) where things begin.","cn":"Japanese uses this in the everyday word 一緒 (issho, 'together'), a compound Chinese doesn't have; Simplified Chinese writes the character 绪."},
  "丈": {"m":"length, height, stature; (unit) jō","on":["ジョウ"],"kun":["たけ"],"rad":[{"c":"丈","m":"a hand (又) holding a staff to measure height"}],"mn":"A hand holding a measuring staff up against a person — taking their height, their stature (丈).","cn":"Chinese 丈夫 (zhàngfu) means 'husband'; Japanese 丈夫 (jōbu) means 'sturdy, healthy, durable' — same characters, very different sense."},
  "夫": {"m":"husband; man, laborer","on":["フ","フウ"],"kun":["おっと"],"rad":[{"c":"大","m":"a standing adult, arms out"},{"c":"一","m":"hairpin of manhood"}],"mn":"A grown adult (大) with the hairpin (一) of manhood in his topknot — a man, a husband (夫).","cn":"大丈夫 (daijōbu) means 'it's OK / all right' in Japanese, but in Chinese 大丈夫 (dà zhàngfu) means 'a real man.'"},
  "当": {"m":"hit the mark, be on target; be correct; this, current","on":["トウ"],"kun":["あ.たる","あ.てる"],"rad":[{"c":"⺌","m":"small cap (from 尚, esteem)"},{"c":"ヨ","m":"hand"}],"mn":"A hand (ヨ) reaching up under the little cap (⺌) and landing dead-on — to hit the mark (当たる).","cn":""},
  "多": {"m":"many, much, a lot","on":["タ"],"kun":["おお.い"],"rad":[{"c":"夕","m":"evening / moon"},{"c":"夕","m":"another evening"}],"mn":"One evening (夕) stacked on another (夕) — night after night piles up into many (多い).","cn":""},
  "疲": {"m":"get tired, fatigue, worn out","on":["ヒ"],"kun":["つか.れる"],"rad":[{"c":"疒","m":"sickness"},{"c":"皮","m":"skin"}],"mn":"When the ache of sickness (疒) reaches your very skin (皮), you are worn out — tired (疲れる).","cn":""},
  "腹": {"m":"belly, abdomen, stomach","on":["フク"],"kun":["はら"],"rad":[{"c":"月","m":"flesh, body"},{"c":"复","m":"return, come again"}],"mn":"The part of the body (月) that keeps coming back (复) for more food — the belly (腹).","cn":""},
  "空": {"m":"sky; empty, vacant; air","on":["クウ"],"kun":["そら","から","あ.く"],"rad":[{"c":"穴","m":"hole, cave"},{"c":"工","m":"work, craft"}],"mn":"A hole (穴) worked (工) clean through — nothing inside, empty, opening onto the sky (空).","cn":""},
  "眠": {"m":"sleep; feel sleepy","on":["ミン"],"kun":["ねむ.る","ねむ.い"],"rad":[{"c":"目","m":"eye"},{"c":"民","m":"the people"}],"mn":"When all the people's (民) eyes (目) fall shut, everyone drifts to sleep (眠る).","cn":""},
  "忙": {"m":"busy, occupied","on":["ボウ"],"kun":["いそが.しい"],"rad":[{"c":"忄","m":"heart"},{"c":"亡","m":"to lose, perish"}],"mn":"So rushed the heart (忄) feels lost (亡) — you are busy (忙しい).","cn":""},
  "昼": {"m":"noon, midday, daytime","on":["チュウ"],"kun":["ひる"],"rad":[{"c":"尺","m":"measure, ruler"},{"c":"旦","m":"sun over the horizon"}],"mn":"Hold a ruler (尺) up to the sun risen high over the ground (旦) at its peak — high noon, midday (昼).","cn":""},
  "美": {"m":"beautiful, pretty","on":["ビ"],"kun":["うつく.しい"],"rad":[{"c":"羊","m":"sheep"},{"c":"大","m":"big"}],"mn":"A big (大), fat sheep (羊) — prized, splendid, a thing of beauty (美しい).","cn":"In Chinese 美 also abbreviates America (美国 Měiguó, USA); Japanese instead uses 米 for America (米国 beikoku)."},
  "味": {"m":"taste, flavor","on":["ミ"],"kun":["あじ","あじ.わう"],"rad":[{"c":"口","m":"mouth"},{"c":"未","m":"not yet"}],"mn":"Into the mouth (口) before you've yet (未) decided — you taste it (味) to find out.","cn":""},
  "走": {"m":"run","on":["ソウ"],"kun":["はし.る"],"rad":[{"c":"土","m":"a runner leaning forward (orig. 夭)"},{"c":"止","m":"foot"}],"mn":"A figure pitched forward (土) driving off the foot (止) below — running flat out (走る).","cn":"In modern Chinese 走 (zǒu) means 'to walk'; Japanese kept the older sense 'to run' (走る hashiru). Chinese uses 跑 (pǎo) for 'run.'"},
  "踊": {"m":"dance; leap, jump","on":["ヨウ"],"kun":["おど.る"],"rad":[{"c":"足","m":"foot"},{"c":"甬","m":"path; well up, spring"}],"mn":"Feet (足) springing up along the path (甬) — leaping and dancing (踊る).","cn":""},
  "運": {"m":"carry, transport; luck, fortune, fate","on":["ウン"],"kun":["はこ.ぶ"],"rad":[{"c":"辶","m":"movement, road"},{"c":"軍","m":"army"}],"mn":"An army (軍) on the move (辶) hauls its supplies onward — to carry (運ぶ), and where fate (運) marches you.","cn":"Simplified Chinese writes this 运 (with 云 inside); Japanese keeps 運 (with 軍, 'army')."},
  "漢": {"m":"Han (China), Chinese; man, fellow","on":["カン"],"kun":[],"rad":[{"c":"氵","m":"water — the Han River"},{"c":"𦰩","m":"clay figure over fire (phonetic)"}],"mn":"The great river (氵), the Han, of China — from it the Han people and their characters (漢字).","cn":"Japanese keeps the traditional 漢; Simplified Chinese writes it 汉. 漢字 (kanji) means 'the Chinese characters' themselves."},
  "字": {"m":"character, letter, written symbol","on":["ジ"],"kun":[],"rad":[{"c":"宀","m":"roof, house"},{"c":"子","m":"child"}],"mn":"A child (子) raised under the roof (宀) — and just as children multiply, so written characters (字) breed more characters.","cn":""},
  "掃": {"m":"sweep, clean","on":["ソウ"],"kun":["は.く"],"rad":[{"c":"扌","m":"hand"},{"c":"帚","m":"broom"}],"mn":"Take the broom (帚) in hand (扌) and sweep the floor clean (掃く).","cn":"Simplified Chinese writes this 扫; Japanese keeps 掃 (with 帚, 'broom')."},
  "除": {"m":"remove, exclude, get rid of; (math) divide","on":["ジョ","ジ"],"kun":["のぞ.く"],"rad":[{"c":"阝","m":"mound, hill"},{"c":"余","m":"surplus, remainder"}],"mn":"Clear the surplus (余) off the hill/mound (阝) — sweep it away, remove it (除く).","cn":""},
  "弾": {"m":"bullet, shell; to play (strings), to bounce / be elastic","on":["ダン"],"kun":["ひ.く","はず.む","たま"],"rad":[{"c":"弓","m":"bow"},{"c":"単","m":"single, simple"}],"mn":"A bow (弓) fires a single (単) shot — the bullet flies, the bowstring snaps back and bounces.","cn":"The traditional form is 彈; Japan simplified it to 弾, mainland China to 弹 — same root, two different modern shapes."},
  "寝": {"m":"to sleep, lie down, go to bed","on":["シン"],"kun":["ね.る","ね.かす"],"rad":[{"c":"宀","m":"roof"},{"c":"爿","m":"bed / split wood"},{"c":"帚","m":"broom"},{"c":"又","m":"hand"}],"mn":"Under the roof (宀), a hand (又) sets the broom (帚) aside and lies on the bed (爿) — time to sleep.","cn":""},
  "起": {"m":"to get up, rise, wake; to occur, begin","on":["キ"],"kun":["お.きる","お.こる","お.こす"],"rad":[{"c":"走","m":"run"},{"c":"己","m":"self, snake"}],"mn":"Your own self (己) breaks into a run (走) — you get up, rise, and things start happening.","cn":""},
  "浴": {"m":"to bathe, be showered with","on":["ヨク"],"kun":["あ.びる","あ.びせる"],"rad":[{"c":"氵","m":"water"},{"c":"谷","m":"valley"}],"mn":"Water (氵) pours down a valley (谷) — stand under it and bathe.","cn":""},
  "歯": {"m":"tooth","on":["シ"],"kun":["は"],"rad":[{"c":"止","m":"stop (phonetic, on top)"},{"c":"凵","m":"open mouth"},{"c":"米","m":"rows of teeth inside"}],"mn":"Stop (止) and open the mouth (凵) — inside sit the neat rows (米) of teeth.","cn":"Japan simplified 齒 to 歯; mainland China simplified the same character to 齿 — two different modern forms."},
  "磨": {"m":"to polish, grind, brush (teeth), hone","on":["マ"],"kun":["みが.く"],"rad":[{"c":"麻","m":"hemp / flax"},{"c":"石","m":"stone"}],"mn":"Rub coarse hemp (麻) against stone (石) until it shines — you polish and grind.","cn":""},
  "顔": {"m":"face; expression, look","on":["ガン"],"kun":["かお"],"rad":[{"c":"彦","m":"fine, accomplished man"},{"c":"頁","m":"head / page"}],"mn":"A fine gentleman (彦) shows his head (頁) — what you see is his face.","cn":"Mainland China writes it 颜 (頁 → 页); Japan keeps the fuller 頁 on the right."},
  "洗": {"m":"to wash, rinse","on":["セン"],"kun":["あら.う"],"rad":[{"c":"氵","m":"water"},{"c":"先","m":"before, ahead"}],"mn":"Reach for water (氵) first (先) of all — wash before you do anything else.","cn":""},
  "風": {"m":"wind; style, manner, appearance","on":["フウ","フ"],"kun":["かぜ","かざ"],"rad":[{"c":"几","m":"wind's frame / table"},{"c":"虫","m":"insect"}],"mn":"Inside the frame (几) an insect (虫) is swept along — carried on the wind.","cn":"Mainland China simplifies this to the very different-looking 风; Japan keeps the fuller 風."},
  "呂": {"m":"spine, backbone; (in 風呂 furo) bath","on":["ロ","リョ"],"kun":[],"rad":[{"c":"口口","m":"two mouths stacked, like spinal vertebrae"}],"mn":"Two mouths (口口) stacked like vertebrae of the spine — and the 'ro' of 風呂, the hot bath.","cn":"呂 first meant 'backbone'; in Chinese 吕 is now mainly the surname Lü. Japanese keeps it alive in 風呂 (furo, bath)."},
  "終": {"m":"to end, finish, conclude","on":["シュウ"],"kun":["お.わる","お.える"],"rad":[{"c":"糸","m":"thread"},{"c":"冬","m":"winter"}],"mn":"The thread (糸) plays out and winter (冬) closes in — everything comes to an end.","cn":""},
  "百": {"m":"hundred","on":["ヒャク"],"kun":[],"rad":[{"c":"一","m":"one"},{"c":"白","m":"white"}],"mn":"One (一) sitting atop white (白) — a single full hundred, a round big number.","cn":""},
  "千": {"m":"thousand","on":["セン"],"kun":["ち"],"rad":[{"c":"丿","m":"a leaning stroke (a person)"},{"c":"十","m":"ten"}],"mn":"A single slash (丿) laid across ten (十) scales it right up — a thousand.","cn":""},
  "万": {"m":"ten thousand; myriad, countless","on":["マン","バン"],"kun":[],"rad":[{"c":"万","m":"myriad (simplified from 萬, once a scorpion pictograph)"}],"mn":"A few quick strokes stand in for the uncountable — ten thousand of everything, a myriad.","cn":"万 is the modern short form of 萬; both Japan and mainland China use 万 today."},
  "円": {"m":"yen (currency); circle, round","on":["エン"],"kun":["まる.い"],"rad":[{"c":"冂","m":"enclosure / open box"},{"c":"|","m":"stroke closing the round shape"}],"mn":"A neat closed enclosure (冂) — a perfect round circle, and the coin called the yen.","cn":"円 is Japan's simplification of 圓 and names the yen; China simplifies 圓 to 圆 and writes its yuan as 元."},
  "金": {"m":"gold; metal; money","on":["キン","コン"],"kun":["かね","かな"],"rad":[{"c":"亼","m":"roof / cover"},{"c":"土","m":"earth"},{"c":"丷","m":"two nuggets"}],"mn":"Under a roof (亼), nuggets (丷) lie buried in the earth (土) — gold, metal, and money.","cn":""},
  "財": {"m":"wealth, assets, property","on":["ザイ","サイ"],"kun":[],"rad":[{"c":"貝","m":"shell / money"},{"c":"才","m":"talent, ability"}],"mn":"Cowrie money (貝) put to good talent (才) piles up into wealth and assets.","cn":"Mainland China writes it 财 (貝 → 贝); Japan keeps the full shell 貝."},
  "布": {"m":"cloth, fabric; to spread, distribute","on":["フ"],"kun":["ぬの"],"rad":[{"c":"𠂇","m":"hand"},{"c":"巾","m":"cloth / hanging towel"}],"mn":"A hand (𠂇) unrolls the hanging cloth (巾) — fabric you spread out and hand round.","cn":""},
  "符": {"m":"tally, token, symbol, charm; (切符) ticket","on":["フ"],"kun":[],"rad":[{"c":"竹","m":"bamboo"},{"c":"付","m":"attach, hand over"}],"mn":"A slip of bamboo (竹) you attach and hand over (付) as a matching tally — a token or ticket.","cn":""},
  "土": {"m":"earth, soil, ground; (土曜) Saturday","on":["ド","ト"],"kun":["つち"],"rad":[{"c":"土","m":"a mound of soil heaped on the ground"}],"mn":"A lump of soil pushed up above the ground line — plain earth and dirt.","cn":"In Japan 土 also names Saturday (土曜日), from the old seven-planet week; Chinese instead says 星期六."},
  "産": {"m":"to give birth, produce; product(s)","on":["サン"],"kun":["う.む","う.まれる","うぶ"],"rad":[{"c":"立","m":"stand"},{"c":"厂","m":"cliff / slope"},{"c":"生","m":"life, birth"}],"mn":"New life (生) stands (立) up out from under the cliff (厂) — birth, and everything produced.","cn":"Mainland China simplifies this to 产; Japan keeps the fuller 産 with 生 underneath."},
  "二": {"m":"two","on":["ニ"],"kun":["ふた","ふた.つ"],"rad":[{"c":"二","m":"two horizontal strokes = the number two"}],"mn":"Two simple parallel strokes — the number two.","cn":""},
  "三": {"m":"three","on":["サン"],"kun":["み","み.つ","みっ.つ"],"rad":[{"c":"三","m":"three horizontal strokes = the number three"}],"mn":"Three stacked strokes — the number three.","cn":""},
  "族": {"m":"family, tribe, clan; group","on":["ゾク"],"kun":[],"rad":[{"c":"方","m":"banner / direction"},{"c":"矢","m":"arrow"}],"mn":"Arrows (矢) rallying under one flying banner (方) — the clan, the whole family gathered.","cn":""},
  "兄": {"m":"older brother","on":["ケイ","キョウ"],"kun":["あに"],"rad":[{"c":"口","m":"mouth"},{"c":"儿","m":"person / legs"}],"mn":"A person (儿) with a big mouth (口) doing the talking and giving orders — the elder brother.","cn":""},
  "弟": {"m":"younger brother","on":["テイ","ダイ"],"kun":["おとうと"],"rad":[{"c":"丷","m":"horns / top mark"},{"c":"弓","m":"bow"},{"c":"丿","m":"a cord winding down in order"}],"mn":"A cord wound in order around a bow (弓) — sequence of birth, so the one who comes after: the younger brother.","cn":""},
  "鳥": {"m":"bird","on":["チョウ"],"kun":["とり"],"rad":[{"c":"鳥","m":"pictograph of a long-tailed bird: head, eye, wing, and feet (灬)"}],"mn":"A whole bird in profile — plume on top, an eye, a folded wing, and the four dots (灬) are its legs and tail, not fire.","cn":""},
  "馬": {"m":"horse","on":["バ"],"kun":["うま","ま"],"rad":[{"c":"馬","m":"pictograph of a horse: flowing mane above, four galloping legs (灬) below"}],"mn":"A horse seen side-on — the mane streams across the top and the four dots (灬) are its galloping legs.","cn":"Simplified Chinese writes this 马; Japanese keeps the full traditional form 馬 with the four-dot legs (灬)."},
  "半": {"m":"half","on":["ハン"],"kun":["なか.ば"],"rad":[{"c":"丷","m":"a splitting mark (from 八, divide)"},{"c":"牛","m":"ox (in the old form, an ox being cut apart)"}],"mn":"Cleave an ox (牛) right down the split-line (丷) and each side is one half.","cn":""},
  "午": {"m":"noon (as in 午前 a.m., 午後 p.m.)","on":["ゴ"],"kun":[],"rad":[{"c":"𠂉","m":"a bent top stroke (like a lost horn)"},{"c":"十","m":"upright stem — a pestle / sundial gnomon"}],"mn":"Like an ox (牛) that has lost one horn — at high noon the sundial's shadow points straight down.","cn":""},
  "議": {"m":"deliberation, discussion","on":["ギ"],"kun":[],"rad":[{"c":"言","m":"words / speech"},{"c":"義","m":"righteousness, justice (羊 sheep + 我 self)"}],"mn":"Trading words (言) over what is right (義) — that is a debate.","cn":""},
  "始": {"m":"begin, start","on":["シ"],"kun":["はじ.める","はじ.まる"],"rad":[{"c":"女","m":"woman"},{"c":"台","m":"platform / pedestal (厶 + 口)"}],"mn":"A woman (女) stands on the pedestal (台) as the origin of life — where everything begins.","cn":""},
  "月": {"m":"moon; month","on":["ゲツ","ガツ"],"kun":["つき"],"rad":[{"c":"月","m":"pictograph of a crescent moon, two lines inside"}],"mn":"A crescent moon hanging in the night sky — and the 'month' whose length it measures.","cn":""},
  "曜": {"m":"day of the week","on":["ヨウ"],"kun":[],"rad":[{"c":"日","m":"sun / day"},{"c":"羽","m":"feathers / wings"},{"c":"隹","m":"small bird"}],"mn":"The sun (日) rises on bright bird-wings (羽 over 隹), lifting into each shining day of the week.","cn":"Japanese names weekdays with 曜 (月曜日 = Monday …); everyday Chinese uses 星期 instead, so 曜 is much rarer in Chinese."},
  "火": {"m":"fire","on":["カ"],"kun":["ひ"],"rad":[{"c":"火","m":"pictograph of rising flames with sparks flying off each side"}],"mn":"A central blaze with sparks leaping off both sides — a burning fire.","cn":""},
  "誕": {"m":"birth, be born","on":["タン"],"kun":[],"rad":[{"c":"言","m":"words / speech"},{"c":"延","m":"stretch, extend, prolong"}],"mn":"Word (言) spreads far and wide (延) that a baby has arrived — a birth (誕生).","cn":""},
  "旅": {"m":"trip, travel, journey","on":["リョ"],"kun":["たび"],"rad":[{"c":"方","m":"a flag / banner (direction)"},{"c":"氏","m":"a band of people marching beneath it"}],"mn":"Under a fluttering banner (方) a band of people (氏) sets off together — a journey.","cn":""},
  "温": {"m":"warm","on":["オン"],"kun":["あたた.かい","あたた.める"],"rad":[{"c":"氵","m":"water"},{"c":"日","m":"sun"},{"c":"皿","m":"dish / bowl"}],"mn":"Water (氵) warmed by the sun (日) and held in a dish (皿) — a warm bath, a warm meal.","cn":""},
  "泉": {"m":"spring, fountain (water source)","on":["セン"],"kun":["いずみ"],"rad":[{"c":"白","m":"white"},{"c":"水","m":"water"}],"mn":"Clear white (白) water (水) bubbling up out of the ground — a natural spring.","cn":""},
  "海": {"m":"sea, ocean","on":["カイ"],"kun":["うみ"],"rad":[{"c":"氵","m":"water"},{"c":"毎","m":"every (from 母, mother)"}],"mn":"Every (毎) stream of water (氵) flows home to its great mother — the sea.","cn":""},
  "泊": {"m":"stay overnight, lodge; moor a boat","on":["ハク"],"kun":["と.まる","と.める"],"rad":[{"c":"氵","m":"water"},{"c":"白","m":"white"}],"mn":"A boat rests on white-capped (白) water (氵) for the night — you moor and lodge.","cn":""},
  "乗": {"m":"ride, board, get on; (math) multiply","on":["ジョウ"],"kun":["の.る","の.せる"],"rad":[{"c":"木","m":"tree / cart"},{"c":"北","m":"a rider's feet astride it (old form 乘)"}],"mn":"In the old form 乘 a person straddles a tree or cart, feet splayed apart (北) — climb up and ride.","cn":"Japanese simplified this to 乗; both traditional and simplified Chinese keep the fuller 乘. The kanji also means 'multiply' in math."},
  "幹": {"m":"trunk (of a tree); main part","on":["カン"],"kun":["みき"],"rad":[{"c":"日","m":"sun"},{"c":"十","m":"sprouting stems"},{"c":"干","m":"dry pole / shield"}],"mn":"A pole (干) rising straight past the sun (日), stems (十) sprouting — a tree's main trunk (the 'main line' 幹 of 新幹線).","cn":""},
  "線": {"m":"line, wire, track","on":["セン"],"kun":[],"rad":[{"c":"糸","m":"thread"},{"c":"泉","m":"spring / fountain"}],"mn":"A thread (糸) drawn out long and flowing like a spring (泉) — a line.","cn":"Simplified Chinese writes this 线; Japanese keeps 線 with the full 泉 (spring) on the right."},
  "富": {"m":"wealth, riches; be abundant","on":["フ"],"kun":["とみ","と.む"],"rad":[{"c":"宀","m":"roof"},{"c":"畐","m":"a jar filled to the brim (one 田-field, one mouth)"}],"mn":"Under the roof (宀) sits a jar filled to the brim (畐) — a wealthy, abundant household.","cn":""},
  "士": {"m":"samurai, warrior; scholar, gentleman","on":["シ"],"kun":[],"rad":[{"c":"十","m":"ten"},{"c":"一","m":"one (the ground)"}],"mn":"Ten (十) skills mastered, grounded on one (一) principle — a scholar-warrior. Note the top stroke is longer than the bottom (unlike 土, earth).","cn":""},
  "城": {"m":"castle","on":["ジョウ"],"kun":["しろ"],"rad":[{"c":"土","m":"earth / soil"},{"c":"成","m":"become, be completed (戈 halberd)"}],"mn":"Earth (土) heaped up and completed (成) into defended ramparts — a castle.","cn":""},
  "桜": {"m":"cherry blossom, cherry tree","on":["オウ"],"kun":["さくら"],"rad":[{"c":"木","m":"tree"},{"c":"丷","m":"tiny blossoms"},{"c":"女","m":"woman"}],"mn":"A tree (木) crowned with a scatter of tiny blossoms (丷), lovely as a woman (女) — the cherry tree.","cn":"Japanese simplified 櫻 to 桜; mainland Chinese simplified the same character differently, to 樱. Both mean cherry blossom."},
  "誘": {"m":"invite, entice, tempt, lure","on":["ユウ"],"kun":["さそ.う"],"rad":[{"c":"言","m":"words / speech"},{"c":"秀","m":"excel, graceful (禾 grain + 乃)"}],"mn":"Graceful, excellent-sounding words (言 + 秀) that draw a person along — an invitation, a temptation.","cn":""},
  "祭": {"m":"festival; to enshrine, worship","on":["サイ"],"kun":["まつ.り","まつ.る"],"rad":[{"c":"⺼","m":"meat (an offering)"},{"c":"又","m":"a hand"},{"c":"示","m":"altar"}],"mn":"A hand (又) laying meat (⺼) upon the altar (示) — the offering that makes a festival.","cn":""},
  "花": {"m":"flower, blossom","on":["カ"],"kun":["はな"],"rad":[{"c":"艹","m":"grass / plant"},{"c":"化","m":"change, transform (also lends the sound)"}],"mn":"Grass (艹) that changes (化) into something bright — a flower opening into bloom.","cn":"Chinese 花 also works as a verb 'to spend' (花钱 spend money); Japanese 花 stays just 'flower/blossom'."},
  "合": {"m":"fit, join, combine; match, suit","on":["ゴウ","ガッ","カッ"],"kun":["あ.う","あ.わせる","あ.わす"],"rad":[{"c":"亼","m":"lid / gather, come together"},{"c":"口","m":"mouth / opening of a vessel"}],"mn":"A lid (亼) drops onto a jar's mouth (口) and fits perfectly — things join and match.","cn":""},
  "残": {"m":"remain, be left over; cruel","on":["ザン"],"kun":["のこ.る","のこ.す"],"rad":[{"c":"歹","m":"bare bones / death"},{"c":"戔","m":"spears, to cut down"}],"mn":"After the spears (戔) fall, only bare bones (歹) are left on the field — what remains.","cn":"Traditional Chinese writes this 殘 (doubled spears); Japanese and simplified Chinese use the reduced form 残."},
  "念": {"m":"thought, feeling, wish; attention, care","on":["ネン"],"kun":[],"rad":[{"c":"今","m":"now (also lends the sound)"},{"c":"心","m":"heart / mind"}],"mn":"What sits on your heart (心) right now (今) — a thought, wish, or worry.","cn":""},
  "荷": {"m":"load, cargo, luggage; burden","on":["カ"],"kun":["に"],"rad":[{"c":"艹","m":"plant"},{"c":"何","m":"what / to carry (also lends the sound)"}],"mn":"A plant-load (艹) — and 何 'what you carry' on your back: baggage and burdens.","cn":"In Chinese 荷 mainly means 'lotus' (荷花); the 'carry/load' sense is secondary. Japanese 荷 (に) is the everyday word for luggage/cargo."},
  "予": {"m":"beforehand, in advance","on":["ヨ"],"kun":["あらかじ.め"],"rad":[{"c":"予","m":"a loom shuttle passed to-and-fro → doing things ahead"}],"mn":"Like a shuttle thrown ahead through the loom, you set things up in advance.","cn":"Japanese 予 covers 'in advance' (予定, 予約); Chinese writes that sense 预, keeping 予 for a literary 'give'."},
  "定": {"m":"fix, settle, decide; certain, regular","on":["テイ","ジョウ"],"kun":["さだ.める","さだ.まる","さだ.か"],"rad":[{"c":"宀","m":"roof / house"},{"c":"疋","m":"foot coming to rest"}],"mn":"Under a roof (宀) your feet (疋) finally come to rest — the matter is settled and fixed.","cn":""},
  "年": {"m":"year; age","on":["ネン"],"kun":["とし"],"rad":[{"c":"禾","m":"grain / harvest"},{"c":"人","m":"person bearing it"}],"mn":"A person (人) carrying home the grain harvest (禾) — one full turn of the seasons: a year.","cn":""},
  "続": {"m":"continue, go on; succeed to","on":["ゾク"],"kun":["つづ.く","つづ.ける"],"rad":[{"c":"糸","m":"thread"},{"c":"売","m":"sell (simplified from 賣; lends the sound)"}],"mn":"A thread (糸) that keeps being paid out (売) without snapping — it goes on and on.","cn":"Traditional/kyūjitai is 續 (糸+賣); Japanese uses 続 (糸+売), simplified Chinese 续 — all mean 'continue'."},
  "頑": {"m":"stubborn, obstinate","on":["ガン"],"kun":[],"rad":[{"c":"元","m":"origin, head (also lends the sound)"},{"c":"頁","m":"head / face"}],"mn":"An original (元), hard head (頁) that will not turn — stubborn to the core.","cn":"Japanese 頑張る (がんばる) 'do your best / hang in there' is a hugely common word; Chinese 顽 (wán) means only 'stubborn/naughty'."},
  "張": {"m":"stretch, spread, put up (tension); (in 頑張る) exert oneself","on":["チョウ"],"kun":["は.る"],"rad":[{"c":"弓","m":"bow"},{"c":"長","m":"long (also lends the sound)"}],"mn":"Draw a bow (弓) out long (長) — the string stretches taut.","cn":""},
  "決": {"m":"decide, determine; (of water) burst through","on":["ケツ"],"kun":["き.める","き.まる"],"rad":[{"c":"氵","m":"water"},{"c":"夬","m":"split off, break open"}],"mn":"Water (氵) bursts through the breach (夬); once it breaks loose, the decision is made.","cn":"Simplified Chinese writes 决 with the two-stroke 'ice' radical (冫); Japanese and traditional Chinese keep the 'water' radical (氵) in 決."},
  "夢": {"m":"dream; vision, ambition","on":["ム"],"kun":["ゆめ"],"rad":[{"c":"艹","m":"drooping eyelashes"},{"c":"目","m":"eye"},{"c":"冖","m":"cover"},{"c":"夕","m":"evening / moon"}],"mn":"At evening (夕), lashes (艹) lower over the eyes (目) and cover (冖) them — you drift into a dream.","cn":""},
  "術": {"m":"art, technique, means, skill; magic","on":["ジュツ"],"kun":["すべ"],"rad":[{"c":"行","m":"crossroads / to go"},{"c":"朮","m":"sticky millet (lends the sound)"}],"mn":"A learned skill you carry through the crossroads (行), clinging like sticky millet (朮) — a technique or art.","cn":"Simplified Chinese reduces this to 术 (just the core, dropping 行); Japanese keeps the full 術."},
  "港": {"m":"port, harbor","on":["コウ"],"kun":["みなと"],"rad":[{"c":"氵","m":"water"},{"c":"巷","m":"lane, alley"}],"mn":"Water (氵) threaded with lanes (巷) of moored ships — a busy harbor.","cn":""},
  "東": {"m":"east","on":["トウ"],"kun":["ひがし"],"rad":[{"c":"木","m":"tree"},{"c":"日","m":"sun"}],"mn":"The sun (日) rising up behind a tree (木) at dawn — the direction east.","cn":"Simplified Chinese writes this 东; Japanese and traditional Chinese keep 東 (as in 東京 Tokyo)."},
  "宿": {"m":"inn, lodging; stay overnight; (astro) constellation","on":["シュク"],"kun":["やど","やど.る","やど.す"],"rad":[{"c":"宀","m":"roof"},{"c":"亻","m":"person"},{"c":"百","m":"hundred (once a sleeping-mat pictograph)"}],"mn":"A hundred (百) travelers (亻) bedded down under one roof (宀) — an inn for the night.","cn":""},
  "絵": {"m":"picture, drawing, painting","on":["カイ","エ"],"kun":[],"rad":[{"c":"糸","m":"thread"},{"c":"会","m":"meet, come together (lends the sound)"}],"mn":"Colored threads (糸) meeting and joining (会) into a woven picture.","cn":"Alone, 絵 is read え — the everyday word for 'picture' (that え is on'yomi エ, not a kun). Traditional/Chinese form: 繪 / 绘."},
  "思": {"m":"think, thought; feel","on":["シ"],"kun":["おも.う"],"rad":[{"c":"田","m":"here from 囟, the crown of the skull / brain"},{"c":"心","m":"heart"}],"mn":"Brain (田, once 囟 'skull') working over the heart (心) — thinking with head and feeling.","cn":""},
  "正": {"m":"correct, right, proper; just; main, positive","on":["セイ","ショウ"],"kun":["ただ.しい","ただ.す","まさ"],"rad":[{"c":"一","m":"a line / the goal"},{"c":"止","m":"foot, to stop"}],"mn":"Your foot (止) halts squarely on the line (一) — right on the mark, correct.","cn":""},
  "違": {"m":"differ, be different; be wrong; violate, disobey","on":["イ"],"kun":["ちが.う","ちが.える"],"rad":[{"c":"辶","m":"movement / road"},{"c":"韋","m":"tanned hide; feet going opposite ways (lends the sound)"}],"mn":"Feet moving (辶) off in opposite directions (韋) — the two go different ways and don't match.","cn":"Japanese 違う (ちがう) is the everyday word for 'be different / be wrong'; Chinese 违 (wéi) means 'violate/disobey', not 'differ'."},
  "問": {"m":"question, ask; problem","on":["モン"],"kun":["と.う","と.い","とん"],"rad":[{"c":"門","m":"gate (lends the sound)"},{"c":"口","m":"mouth"}],"mn":"Bring your mouth (口) up to the gate (門) and call out — you ask a question.","cn":""},
  "題": {"m":"topic, subject, title; exam problem","on":["ダイ"],"kun":[],"rad":[{"c":"是","m":"this, right (lends the sound)"},{"c":"頁","m":"head / page"}],"mn":"The very (是) matter at the head (頁) of things — the topic, title, or problem set.","cn":""},
  "答": {"m":"answer, reply, respond","on":["トウ"],"kun":["こた.える","こた.え"],"rad":[{"c":"竹","m":"bamboo"},{"c":"合","m":"fit, match (lends the sound)"}],"mn":"A bamboo (竹) tally that fits (合) the question exactly — the matching answer.","cn":""},
  "意": {"m":"mind, will, intention; meaning, thought","on":["イ"],"kun":[],"rad":[{"c":"音","m":"sound"},{"c":"心","m":"heart"}],"mn":"The sound (音) that rises straight from the heart (心) — your true meaning and intent.","cn":""},
  "葉": {"m":"leaf, foliage; counter for flat thin things; blade (of grass)","on":["ヨウ"],"kun":["は"],"rad":[{"c":"艹","m":"grass / plant"},{"c":"世","m":"generation"},{"c":"木","m":"tree"}],"mn":"Plants (艹) put out generation after generation (世) of leaves on the tree (木).","cn":"Simplified Chinese writes leaf as 叶 (also a surname); Japanese keeps the full form 葉."},
  "文": {"m":"writing, text, sentence; literature; culture","on":["ブン","モン"],"kun":["ふみ"],"rad":[{"c":"文","m":"crossed markings on a chest — pattern (pictograph)"}],"mn":"A figure with crossed markings (文) on the chest — patterns became writing, literature, culture.","cn":""},
  "化": {"m":"change, transform; take the form of; -ization","on":["カ","ケ"],"kun":["ば.ける","ば.かす"],"rad":[{"c":"亻","m":"person"},{"c":"匕","m":"person turned upside down / spoon"}],"mn":"One person upright (亻), one flipped over (匕) — a figure mid-change, becoming something else.","cn":""},
  "歴": {"m":"history; the passage of time; successive, one after another","on":["レキ"],"kun":[],"rad":[{"c":"厂","m":"cliff / slope"},{"c":"禾","m":"grain (shown doubled)"},{"c":"止","m":"foot / stop"}],"mn":"Feet (止) walking past rows of grain (禾禾) beneath a cliff (厂) — the long march of history.","cn":"Simplified Chinese writes this 历 (which also absorbs 暦 'calendar'); Japanese keeps 歴 for history and 暦 for calendar."},
  "史": {"m":"history, chronicle; historian, record-keeper","on":["シ"],"kun":[],"rad":[{"c":"中","m":"tally sticks in a holder"},{"c":"又","m":"hand"}],"mn":"A hand (又) gripping the box of tally-records (中) — the chronicler who keeps the history.","cn":""},
  "実": {"m":"truth, reality; fruit, nut; sincere","on":["ジツ"],"kun":["み","みの.る"],"rad":[{"c":"宀","m":"roof / house"},{"c":"大","m":"big / abundance below"}],"mn":"Under the roof (宀) goods pile up big (大) and real — substance, truth; the fruit a plant truly bears.","cn":"Three shapes, one idea: traditional 實, simplified Chinese 实, Japanese 実 — all mean 'real/solid/fruit'."},
  "許": {"m":"permit, allow; forgive; approximately","on":["キョ"],"kun":["ゆる.す"],"rad":[{"c":"言","m":"words / speech"},{"c":"午","m":"noon (phonetic)"}],"mn":"The word (言) spoken at noon (午) that grants leave — you're permitted, allowed, forgiven.","cn":"Simplified Chinese 许; besides 'allow' it also means 'perhaps' (也许) and is a common surname."},
  "暗": {"m":"dark; unseen, hidden; by heart (暗記)","on":["アン"],"kun":["くら.い"],"rad":[{"c":"日","m":"sun / day"},{"c":"音","m":"sound (phonetic)"}],"mn":"When the sun (日) is gone and only sound (音) remains — darkness.","cn":""},
  "殺": {"m":"kill, murder; reduce, diminish (相殺 offset)","on":["サツ","サイ"],"kun":["ころ.す"],"rad":[{"c":"乂","m":"cut / slash"},{"c":"木","m":"tree"},{"c":"殳","m":"weapon in hand / to strike"}],"mn":"A slash (乂) at the tree (木) with a weapon in hand (殳) — to strike down, to kill.","cn":"Simplified Chinese writes this 杀; Japanese keeps 殺."},
  "鷲": {"m":"eagle","on":[],"kun":["わし"],"rad":[{"c":"就","m":"accomplish (phonetic)"},{"c":"鳥","m":"bird"}],"mn":"The bird (鳥) that accomplishes (就) the kill from on high — the eagle.","cn":""},
  "隠": {"m":"hide, conceal; secret","on":["イン"],"kun":["かく.す","かく.れる"],"rad":[{"c":"阝","m":"hill / mound"},{"c":"爫","m":"covering hand"},{"c":"心","m":"heart"}],"mn":"Behind the hill (阝) a hand (爫) covers the heart (心) — feelings hidden away.","cn":"Simplified Chinese writes this 隐; Japanese keeps 隠."},
  "信": {"m":"trust, believe; faith; message, signal (信号)","on":["シン"],"kun":[],"rad":[{"c":"亻","m":"person"},{"c":"言","m":"words / speech"}],"mn":"A person (亻) who stands by their word (言) — someone you trust and believe.","cn":""},
  "条": {"m":"clause, article (of law); line, stripe; counter for items","on":["ジョウ"],"kun":[],"rad":[{"c":"夂","m":"go / follow (top)"},{"c":"木","m":"tree / branch"}],"mn":"A slender branch running off the tree (木) — a single line, a clause, an article of law.","cn":"Japanese 条 matches the simplified-Chinese shape 条; the traditional form is 條."},
  "説": {"m":"explain; theory, opinion; rumor","on":["セツ","ゼイ"],"kun":["と.く"],"rad":[{"c":"言","m":"words / speech"},{"c":"兌","m":"exchange / delight (phonetic)"}],"mn":"With pleasing words (言 + 兌) you lay out your theory and talk them round.","cn":"Simplified Chinese 说 (shuō) is the everyday word for 'to say/speak'; Japanese 説 leans to 'explain/theory' (説明, 小説) — 'say' is 言う."},
  "場": {"m":"place, spot; scene; occasion; counter for scenes","on":["ジョウ"],"kun":["ば"],"rad":[{"c":"土","m":"earth / ground"},{"c":"昜","m":"rising sun / rays (phonetic)"}],"mn":"Sunlit (昜) open ground (土) — a place, a spot, a scene where things happen.","cn":"Simplified Chinese writes this 场; Japanese keeps 場."},
  "所": {"m":"place, spot; office; the thing which (nominalizer)","on":["ショ"],"kun":["ところ"],"rad":[{"c":"戸","m":"door"},{"c":"斤","m":"axe"}],"mn":"By the door (戸) where the axe (斤) hangs — one particular place, a spot.","cn":""},
  "世": {"m":"world; generation; era; society","on":["セ","セイ"],"kun":["よ"],"rad":[{"c":"世","m":"three tens joined = thirty years / a generation (pictograph)"}],"mn":"Three tens (十十十) bound together — thirty years, one generation, one age of the world.","cn":""},
  "界": {"m":"world; boundary; sphere, field (as suffix)","on":["カイ"],"kun":[],"rad":[{"c":"田","m":"rice field"},{"c":"介","m":"between / mediate (phonetic)"}],"mn":"The lines that come between (介) the fields (田) — boundaries dividing up the world.","cn":""},
  "未": {"m":"not yet; un-, in-; (zodiac) the Ram","on":["ミ"],"kun":["いま.だ"],"rad":[{"c":"木","m":"tree"},{"c":"一","m":"short upper branch, not yet grown"}],"mn":"A tree (木) whose topmost branch is still short (一) — growth not finished: 'not yet'.","cn":""},
  "過": {"m":"pass by; exceed, surpass; error, fault","on":["カ"],"kun":["す.ぎる","す.ごす","あやま.ち"],"rad":[{"c":"辶","m":"movement / road"},{"c":"咼","m":"crooked, twisted (phonetic)"}],"mn":"Walking (辶) a crooked path (咼) — you pass by, go too far, and now and then err.","cn":"Simplified Chinese writes this 过; there 过 (guò) is also the everyday verb 'to cross/pass'."},
  "去": {"m":"leave, depart; the past; remove, eliminate","on":["キョ","コ"],"kun":["さ.る"],"rad":[{"c":"土","m":"earth / ground"},{"c":"厶","m":"private / self (originally a pit-dwelling)"}],"mn":"Stepping off your own ground (土) away from self (厶) — you leave, and it becomes the past.","cn":"Chinese 去 (qù) is the everyday 'to go (somewhere)'; Japanese 去る leans the opposite — 'to leave, go away' — while 去 mostly supplies 'past' (過去) and 'remove'."},
  "記": {"m":"write down, record; note; account, chronicle","on":["キ"],"kun":["しる.す"],"rad":[{"c":"言","m":"words / speech"},{"c":"己","m":"self, oneself (phonetic)"}],"mn":"Setting words (言) down for yourself (己) — you record it, you note it.","cn":""},
  "憶": {"m":"remember, recall; think, suppose; memory","on":["オク"],"kun":[],"rad":[{"c":"忄","m":"heart / feeling"},{"c":"意","m":"thought / mind"}],"mn":"Holding a thought (意) close in the heart (忄) — you remember it.","cn":"Simplified Chinese writes this 忆 (as in 记忆, memory); Japanese keeps 憶."},
  "祖": {"m":"ancestor, forefather; founder, originator","on":["ソ"],"kun":[],"rad":[{"c":"礻","m":"altar / ritual (spirit)"},{"c":"且","m":"stacked ancestral tablets (phonetic)"}],"mn":"At the altar (礻) stand the stacked tablets (且) of the forefathers — your ancestors, the founders.","cn":""},
  "秘": {"m":"secret; conceal; mysterious","on":["ヒ"],"kun":["ひ.める"],"rad":[{"c":"禾","m":"grain (modern form; originally 示, altar)"},{"c":"必","m":"certainly, must (phonetic)"}],"mn":"What must (必) stay locked in the grain-store (禾) — kept secret, hidden, mysterious.","cn":""},
  "密": {"m":"secret; dense, close, minute","on":["ミツ"],"kun":["ひそ.か"],"rad":[{"c":"宀","m":"roof / house"},{"c":"必","m":"certainly, without fail"},{"c":"山","m":"mountain"}],"mn":"Under a roof (宀) it is certainly (必) hidden away behind a mountain (山) — dense and secret.","cn":""},
  "探": {"m":"search for, look for; explore, probe","on":["タン"],"kun":["さぐ.る","さが.す"],"rad":[{"c":"扌","m":"hand"},{"c":"罙","m":"reaching deep into a hollow (shared with 深 'deep')"}],"mn":"A hand (扌) reaching deep into a hollow (罙) to feel around — you search and explore.","cn":""},
  "械": {"m":"machine, device (as in 機械)","on":["カイ"],"kun":[],"rad":[{"c":"木","m":"wood / tree"},{"c":"戒","m":"guard against, admonish (two hands 廾 gripping a halberd 戈)"}],"mn":"A wooden (木) contraption you handle with guarded care (戒) — a machine or tool.","cn":""},
  "塔": {"m":"tower, pagoda","on":["トウ"],"kun":[],"rad":[{"c":"土","m":"earth / soil"},{"c":"艹","m":"plants / grass"},{"c":"合","m":"join, fit together"}],"mn":"Earth (土) and plants (艹) joined (合) and stacked ever higher — a tower or pagoda.","cn":""},
  "頭": {"m":"head","on":["トウ","ズ","ト"],"kun":["あたま","かしら"],"rad":[{"c":"豆","m":"bean (phonetic)"},{"c":"頁","m":"the 'big head' radical (a head + neck)"}],"mn":"A bean (豆) perched atop the big-head radical (頁) — that round thing is your head.","cn":"Mainland China simplifies 頭 to 头; Japan keeps the traditional 頭."},
  "痛": {"m":"pain, ache; hurt","on":["ツウ"],"kun":["いた.い","いた.む","いた.める"],"rad":[{"c":"疒","m":"sickness / illness radical"},{"c":"甬","m":"surge through (phonetic, as in 通 'pass through')"}],"mn":"A sickness (疒) that surges right through you (甬, like 通) — that is pain.","cn":""},
  "邪": {"m":"wicked, evil; harmful","on":["ジャ"],"kun":["よこしま"],"rad":[{"c":"牙","m":"tusk / fang"},{"c":"阝","m":"village (right-side 邑)"}],"mn":"Fangs (牙) bared over the village (阝) — a wicked, evil presence.","cn":"Japanese 風邪 (かぜ) just means 'a common cold'; in Chinese 風邪 (fēngxié) is the Traditional-Chinese-Medicine 'wind-evil' pathogen."},
  "熱": {"m":"heat; fever; hot; zeal","on":["ネツ"],"kun":["あつ.い"],"rad":[{"c":"埶","m":"planting, cultivating (as in 勢 / 芸)"},{"c":"灬","m":"fire"}],"mn":"Fire (灬) tended and cultivated (埶) underneath, building and building — heat, fever, zeal.","cn":"Mainland China simplifies 熱 to 热; Japan keeps 熱."},
  "薬": {"m":"medicine, drug","on":["ヤク"],"kun":["くすり"],"rad":[{"c":"艹","m":"grass / herb"},{"c":"楽","m":"ease, comfort, pleasure"}],"mn":"The herb (艹) that brings you ease and comfort (楽) — medicine.","cn":"Japan's 薬 is its own simplified form; the traditional/Chinese character is 藥, and mainland China simplifies it to 药."},
  "病": {"m":"illness, sickness; disease","on":["ビョウ","ヘイ"],"kun":["や.む","やまい"],"rad":[{"c":"疒","m":"sickness / illness radical"},{"c":"丙","m":"'third' (phonetic)"}],"mn":"The sickness radical (疒) laid over 丙 — you have fallen ill; disease.","cn":""},
  "院": {"m":"institution (hospital, temple, school); the '院' of 病院 hospital","on":["イン"],"kun":[],"rad":[{"c":"阝","m":"hill / mound (left-side 阜)"},{"c":"完","m":"complete (roof 宀 over 元 'origin')"}],"mn":"A walled hill (阝) enclosing a complete, finished (完) compound — a great institution.","cn":"Japanese 'hospital' is 病院; Chinese uses 医院 (yīyuàn), and Japanese 医院 means only a small clinic."},
  "外": {"m":"outside, exterior; other","on":["ガイ","ゲ"],"kun":["そと","ほか","はず.す","はず.れる"],"rad":[{"c":"夕","m":"evening"},{"c":"卜","m":"divination (a cracked oracle bone)"}],"mn":"Divining (卜) in the evening (夕) — done off-schedule, outside the proper order: outside.","cn":""},
  "国": {"m":"country, nation","on":["コク"],"kun":["くに"],"rad":[{"c":"囗","m":"enclosure / border"},{"c":"玉","m":"jewel / precious jade"}],"mn":"Within its borders (囗) a nation guards its jewel (玉) — the country.","cn":"Japan and mainland China both simplified 國 to 国; Taiwan and Hong Kong keep the traditional 國 (囗 around 或)."},
  "声": {"m":"voice; sound","on":["セイ","ショウ"],"kun":["こえ","こわ"],"rad":[{"c":"声","m":"a hanging stone chime being struck — the sound-making top of 聲"}],"mn":"A struck stone chime rings out — voice, sound. Japan trimmed the full 聲 down to just this piece.","cn":"Both Japan and mainland China reduced 聲 to 声; Taiwan and Hong Kong keep the full 聲."},
  "払": {"m":"pay; sweep away, clear off","on":["フツ"],"kun":["はら.う"],"rad":[{"c":"扌","m":"hand"},{"c":"ム","m":"simplified stand-in for 弗 ('not')"}],"mn":"A hand (扌) sweeping something clean away — you brush the money out and pay.","cn":"払 is a Japan-only simplified form of 拂 (brush away); Chinese still writes 拂, and uses 付 for 'pay'."},
  "約": {"m":"promise; approximately, about; reduce","on":["ヤク"],"kun":[],"rad":[{"c":"糹","m":"thread / silk"},{"c":"勺","m":"ladle, dipper (phonetic)"}],"mn":"Tie a thread (糹) tight around a ladleful (勺) — you bind it down: a promise, or a rough measure ('about').","cn":"Mainland China simplifies 約 to 约; Japan keeps 約."},
  "準": {"m":"standard, level; semi-, quasi-","on":["ジュン"],"kun":[],"rad":[{"c":"氵","m":"water — always finds a level surface"},{"c":"隹","m":"short-tailed bird"},{"c":"十","m":"ten (base)"}],"mn":"Water (氵) always settles perfectly level — the standard to measure against, sure as a falcon (隼) locks on its mark.","cn":"Mainland China writes this 准 (merging 準 into 准); Japan keeps 準 as a distinct character."},
  "備": {"m":"prepare, provide; equip","on":["ビ"],"kun":["そな.える","そな.わる"],"rad":[{"c":"亻","m":"person"},{"c":"𤰇","m":"a quiver of arrows kept at the ready"}],"mn":"A person (亻) keeping a full quiver of arrows (𤰇) always at hand — prepared and equipped.","cn":"Mainland China simplifies 備 to 备; Japan keeps 備."},
  "発": {"m":"depart, set off; emit, issue","on":["ハツ","ホツ"],"kun":[],"rad":[{"c":"癶","m":"two feet stepping outward — setting off"}],"mn":"Two feet stepping outward (癶) — you set off and depart, and shots are fired off. Japan trimmed the bow (弓) out of the older 發.","cn":"発 is the Japanese simplified form of 發 (emit / depart); mainland China simplifies the same character to 发."},
  "到": {"m":"arrive, reach; attain","on":["トウ"],"kun":[],"rad":[{"c":"至","m":"reach, arrive at the limit"},{"c":"刂","m":"knife / blade (right-side 刀, phonetic)"}],"mn":"Push clear to the utmost limit (至), sharp as a blade (刂) — you arrive, you attain it.","cn":""},
  "着": {"m":"wear, put on; arrive; attach","on":["チャク","ジャク"],"kun":["き.る","き.せる","つ.く","つ.ける"],"rad":[{"c":"羊","m":"sheep (abbreviated, on top)"},{"c":"目","m":"eye"}],"mn":"Draw a sheep's (羊) fleece down over your eyes (目) — you put it on and wear it; also 'arrive' and 'attach.'","cn":"Japanese splits the old 著 into 着 (wear / arrive) and 著 (author, prominent); in Chinese 着 is also a very common aspect particle (-zhe)."},
  "忘": {"m":"forget","on":["ボウ"],"kun":["わす.れる"],"rad":[{"c":"亡","m":"lose, perish (phonetic and 'gone')"},{"c":"心","m":"heart / mind"}],"mn":"When something is lost (亡) out of your heart-mind (心) — you have forgotten it.","cn":""},
  "早": {"m":"early; fast, quick","on":["ソウ","サッ"],"kun":["はや.い","はや.まる","はや.める"],"rad":[{"c":"日","m":"sun"},{"c":"十","m":"ten (a marker below)"}],"mn":"The sun (日) already risen above the mark (十) at first light — early.","cn":""},
  "急": {"m":"hurry, urgent; sudden; steep","on":["キュウ"],"kun":["いそ.ぐ"],"rad":[{"c":"刍","m":"a hand grasping / catching up (cursive of 及 'reach')"},{"c":"心","m":"heart"}],"mn":"A hand grabbing (刍, from 及 'to reach') at your pounding heart (心) — hurry, urgency.","cn":""},
  "塩": {"m":"salt","on":["エン"],"kun":["しお"],"rad":[{"c":"土","m":"earth"},{"c":"口","m":"mouth / opening"},{"c":"皿","m":"dish / plate"}],"mn":"Brine drawn from the earth (土) and dried in a dish (皿), then tasted on the tongue (口) — salt.","cn":"Three different forms for 'salt': Japanese 塩, traditional Chinese 鹽, and mainland-simplified 盐."},
  "砂": {"m":"sand, grit","on":["サ","シャ"],"kun":["すな"],"rad":[{"c":"石","m":"stone, rock"},{"c":"少","m":"few, small"}],"mn":"Stone (石) worn down into countless tiny (少) bits — sand.","cn":""},
  "糖": {"m":"sugar","on":["トウ"],"kun":[],"rad":[{"c":"米","m":"rice, grain"},{"c":"唐","m":"Tang China / phonetic"}],"mn":"Grain (米) refined the way it came from Tang China (唐) — into sweet sugar (砂糖).","cn":""},
  "甘": {"m":"sweet; to be lenient / spoil","on":["カン"],"kun":["あま.い","あま.える","あま.やかす"],"rad":[{"c":"甘","m":"a mouth holding something on the tongue"}],"mn":"A mouth (口-like) with a mark inside — something held on the tongue to savor its sweetness.","cn":""},
  "辛": {"m":"spicy, hot; hard, painful","on":["シン"],"kun":["から.い","つら.い"],"rad":[{"c":"辛","m":"a tattooing needle (a mark of punishment)"}],"mn":"Originally a sharp needle used to brand a captive — a sting that is both 'hot/spicy' and 'bitterly hard'.","cn":""},
  "健": {"m":"healthy, robust, sound","on":["ケン"],"kun":["すこ.やか"],"rad":[{"c":"亻","m":"person"},{"c":"建","m":"build, erect"}],"mn":"A person (亻) soundly built (建) stands strong — healthy.","cn":""},
  "康": {"m":"health, ease, peace","on":["コウ"],"kun":[],"rad":[{"c":"广","m":"roof, shelter"},{"c":"氺","m":"scattered grains (from threshed rice)"}],"mn":"Under a roof (广) with grain aplenty spilling out (氺) — a life of ease and health (健康).","cn":""},
  "野": {"m":"field, open plain; wild","on":["ヤ"],"kun":["の"],"rad":[{"c":"里","m":"village, hamlet"},{"c":"予","m":"beforehand / phonetic"}],"mn":"The land reaching out from the village (里) — open, untamed fields.","cn":""},
  "菜": {"m":"vegetable, greens","on":["サイ"],"kun":["な"],"rad":[{"c":"艹","m":"grass, plant"},{"c":"采","m":"pick, pluck"}],"mn":"The plants (艹) you pick (采) by hand to eat — vegetables (野菜).","cn":"Chinese 菜 (cài) broadly covers 'dish/cuisine/food' too (川菜, 点菜); Japanese leans on 菜 mainly for 'greens/vegetables'."},
  "果": {"m":"fruit; result, outcome","on":["カ"],"kun":["は.たす","は.てる","は.て"],"rad":[{"c":"田","m":"round fruit (drawn like a field)"},{"c":"木","m":"tree"}],"mn":"Round fruit (田) hanging on the tree (木) — what the tree finally produces, its result.","cn":""},
  "体": {"m":"body; form, substance","on":["タイ","テイ"],"kun":["からだ"],"rad":[{"c":"亻","m":"person"},{"c":"本","m":"origin, root, base"}],"mn":"A person's (亻) fundamental base (本) — the body that carries everything else.","cn":"Traditional Chinese is 體; both Japanese shinjitai and simplified Chinese settled on 体."},
  "動": {"m":"move, motion","on":["ドウ"],"kun":["うご.く","うご.かす"],"rad":[{"c":"重","m":"heavy"},{"c":"力","m":"power, strength"}],"mn":"It takes strength (力) to shift something heavy (重) — to move.","cn":""},
  "星": {"m":"star","on":["セイ","ショウ"],"kun":["ほし"],"rad":[{"c":"日","m":"sun (here: a sparkling star)"},{"c":"生","m":"life, be born, grow"}],"mn":"A tiny sun (日) born (生) into the night sky — a star.","cn":""},
  "地": {"m":"ground, earth, land","on":["チ","ジ"],"kun":[],"rad":[{"c":"土","m":"soil, earth"},{"c":"也","m":"serpent / phonetic"}],"mn":"Soil (土) winding on and on (也) — the ground beneath us.","cn":""},
  "球": {"m":"ball, sphere; globe","on":["キュウ"],"kun":["たま"],"rad":[{"c":"玉","m":"jade, jewel (王-shape as radical)"},{"c":"求","m":"seek, request"}],"mn":"The jewel (玉) everyone seeks (求) is round and perfect — a sphere; the earth is 地球.","cn":""},
  "暖": {"m":"warm (weather, temperature)","on":["ダン"],"kun":["あたた.かい","あたた.まる","あたた.める"],"rad":[{"c":"日","m":"sun"},{"c":"爰","m":"a hand reaching / pulling"}],"mn":"The sun (日) stretching its rays out (爰) to reach you — warm.","cn":""},
  "涼": {"m":"cool, refreshing","on":["リョウ"],"kun":["すず.しい","すず.む"],"rad":[{"c":"氵","m":"water"},{"c":"京","m":"capital, high hill"}],"mn":"Water (氵) off a high hilltop (京) — a cool, refreshing breeze.","cn":""},
  "覚": {"m":"remember, learn; awaken, perceive","on":["カク"],"kun":["おぼ.える","さ.ます","さ.める"],"rad":[{"c":"⺍","m":"the 'small/学' crown (three short strokes)"},{"c":"見","m":"see, look"}],"mn":"When learning (the 学 crown) makes you truly see (見) — you awaken to it and it sticks in memory.","cn":"Japanese shinjitai 覚 simplifies the top of 覺; Traditional Chinese keeps 覺, simplified Chinese writes 觉."},
  "計": {"m":"measure, count; plan, total","on":["ケイ"],"kun":["はか.る","はか.らう"],"rad":[{"c":"言","m":"words, speech"},{"c":"十","m":"ten"}],"mn":"Putting words (言) to a full tally of ten (十) — to count, measure, and plan.","cn":""},
  "母": {"m":"mother","on":["ボ"],"kun":["はは"],"rad":[{"c":"母","m":"a woman with two breasts (the two dots) to nurse"}],"mn":"The figure of a woman with two dots for breasts — the one who nurses: mother.","cn":""},
  "父": {"m":"father","on":["フ"],"kun":["ちち"],"rad":[{"c":"父","m":"a hand gripping a stone axe / tool"}],"mn":"A hand wielding an axe to work and provide — father.","cn":""},
  "両": {"m":"both, two; old gold unit (ryō)","on":["リョウ"],"kun":[],"rad":[{"c":"両","m":"a balance beam with two equal, matched pans"}],"mn":"A scale with two evenly matched pans hanging side by side — both, the pair.","cn":"Japanese 両 (from 兩); Traditional Chinese 兩, simplified Chinese 两 — three distinct shapes for the same 'both/pair'."},
  "彼": {"m":"he; that one over there","on":["ヒ"],"kun":["かれ","かの"],"rad":[{"c":"彳","m":"step, going (a road)"},{"c":"皮","m":"skin, hide / phonetic"}],"mn":"Someone glimpsed a walk (彳) away, just their skin (皮) at a distance — 'that one over there', hence 'he'.","cn":"Chinese says 他 for 'he'; Japanese repurposed 彼 ('that one yonder') as everyday 'he' — 彼女 'she/girlfriend', 彼氏 'boyfriend'."},
  "女": {"m":"woman, female","on":["ジョ","ニョ","ニョウ"],"kun":["おんな","め"],"rad":[{"c":"女","m":"a woman kneeling with folded arms"}],"mn":"The drawn figure of a woman kneeling with arms folded — female.","cn":""},
  "貸": {"m":"lend, loan out","on":["タイ"],"kun":["か.す"],"rad":[{"c":"代","m":"substitute, in place of"},{"c":"貝","m":"shell (= money)"}],"mn":"Handing over your money (貝) as a stand-in (代), expecting it back — to lend.","cn":""},
  "借": {"m":"borrow","on":["シャク"],"kun":["か.りる"],"rad":[{"c":"亻","m":"person"},{"c":"昔","m":"long ago, former times"}],"mn":"A person (亻) taking another's thing for a while (昔, 'a time') before giving it back — to borrow.","cn":"Japanese splits 借りる 'borrow' vs 貸す 'lend'; Chinese 借 (jiè) can mean both borrow and lend depending on context."},
  "教": {"m":"teach; faith, doctrine","on":["キョウ"],"kun":["おし.える","おそ.わる"],"rad":[{"c":"耂","m":"old man / elder"},{"c":"子","m":"child"},{"c":"攵","m":"strike / rap a stick, action"}],"mn":"An elder (耂) taps a child (子) with a stick (攵) to drill in a lesson — to teach.","cn":""},
  "送": {"m":"send, dispatch; see (someone) off","on":["ソウ"],"kun":["おく.る"],"rad":[{"c":"辶","m":"road / movement"},{"c":"关","m":"a gift held out in both hands"}],"mn":"Carry the gift (关) down the road (辶) to someone — to send it off.","cn":""},
  "案": {"m":"plan, proposal, idea; (orig.) desk, table","on":["アン"],"kun":[],"rad":[{"c":"安","m":"peace / calm"},{"c":"木","m":"tree / wood"}],"mn":"Sit calm (安) at a wooden (木) desk and draft a plan.","cn":""},
  "内": {"m":"inside, within; home, one's own group","on":["ナイ","ダイ"],"kun":["うち"],"rad":[{"c":"冂","m":"enclosure / boundary"},{"c":"人","m":"person"}],"mn":"A person (人) tucked inside a boundary (冂) — inside, at home.","cn":""},
  "直": {"m":"straight; direct; honest; to fix, repair","on":["チョク","ジキ"],"kun":["なお.す","なお.る","ただ.ちに"],"rad":[{"c":"十","m":"ten / a straight line"},{"c":"目","m":"eye"},{"c":"乚","m":"hidden hook / corner"}],"mn":"Line ten (十) eyes (目) up in a row and sight straight down — direct and honest.","cn":""},
  "道": {"m":"road, way, path; the Way (Tao); a discipline","on":["ドウ","トウ"],"kun":["みち"],"rad":[{"c":"辶","m":"road / movement"},{"c":"首","m":"head / neck"}],"mn":"Point your head (首) forward and move (辶) — that is the road, the way.","cn":""},
  "姉": {"m":"older sister","on":["シ"],"kun":["あね"],"rad":[{"c":"女","m":"woman"},{"c":"市","m":"market / town"}],"mn":"The woman (女) old enough to run the market (市) errands — your big sister.","cn":"Everyday Chinese writes 'older sister' as 姐 (jiě); Japanese uses 姉 (a form of the classical 姊)."},
  "経": {"m":"pass through, elapse; manage; sutra; longitude","on":["ケイ","キョウ"],"kun":["へ.る","た.つ"],"rad":[{"c":"糸","m":"thread / silk"},{"c":"巠","m":"vertical warp threads / underground streams"}],"mn":"The lengthwise warp threads (巠) strung on the loom (糸) run right through — to pass through.","cn":"Japanese 経, traditional Chinese 經, simplified Chinese 经 — three shapes of one character."},
  "験": {"m":"test, examine, verify; effect, result","on":["ケン","ゲン"],"kun":[],"rad":[{"c":"馬","m":"horse"},{"c":"㑒","m":"gather all together"}],"mn":"Round up all (㑒) the horses (馬) and inspect them — a test of quality.","cn":"Japanese 験, traditional Chinese 驗, simplified Chinese 验."},
  "登": {"m":"climb, ascend; register (as in 登録)","on":["トウ","ト"],"kun":["のぼ.る"],"rad":[{"c":"癶","m":"two feet stepping apart"},{"c":"豆","m":"bean / raised ritual vessel"}],"mn":"Two feet (癶) step up onto the raised platform (豆) — to climb.","cn":""},
  "抹": {"m":"erase, rub out, wipe; paint over; powder (抹茶 matcha)","on":["マツ"],"kun":[],"rad":[{"c":"扌","m":"hand"},{"c":"末","m":"tip / far end"}],"mn":"Your hand (扌) wipes clean right to the far end (末) — erase it, rub it out.","cn":""},
  "最": {"m":"most, -est; the utmost","on":["サイ"],"kun":["もっと.も"],"rad":[{"c":"冃","m":"cap / cover on top"},{"c":"取","m":"take (grab with hand + ear)"}],"mn":"Reach to the very top (冃) and grab (取) the prize — the most, the best.","cn":""},
  "昔": {"m":"long ago, ancient times, former days","on":["セキ","シャク"],"kun":["むかし"],"rad":[{"c":"龷","m":"piled-up layers"},{"c":"日","m":"sun / day"}],"mn":"Days (日) stacked in layers (龷) upon layers — long, long ago.","cn":""},
  "初": {"m":"first, beginning; the first time","on":["ショ"],"kun":["はじ.め","はつ","うい","そ.める"],"rad":[{"c":"衤","m":"clothing / robe"},{"c":"刀","m":"knife / sword"}],"mn":"Taking a knife (刀) to the cloth (衤) is the first cut in making a garment — the beginning.","cn":""},
  "久": {"m":"long time, long-lasting","on":["キュウ","ク"],"kun":["ひさ.しい"],"rad":[{"c":"久","m":"a figure held back from behind, lingering"}],"mn":"A person dragged back from leaving, made to linger and linger — a long, long time.","cn":""},
  "押": {"m":"push, press; hold down; stamp, seal","on":["オウ"],"kun":["お.す","お.さえる"],"rad":[{"c":"扌","m":"hand"},{"c":"甲","m":"armor / shell, first"}],"mn":"Your hand (扌) presses down hard on the armor plate (甲) — push, press.","cn":""},
  "咲": {"m":"bloom, blossom (of flowers)","on":[],"kun":["さ.く"],"rad":[{"c":"口","m":"mouth"},{"c":"关","m":"a smiling, dancing figure"}],"mn":"A mouth (口) breaking into a smile (关) — flowers 'smile' open when they bloom.","cn":"In Chinese 咲 is an old variant of 笑 'laugh, smile'; Japanese repurposed it to mean 'bloom'."},
  "困": {"m":"be troubled, distressed, at a loss, perplexed","on":["コン"],"kun":["こま.る"],"rad":[{"c":"囗","m":"enclosure / box"},{"c":"木","m":"tree"}],"mn":"A tree (木) boxed in (囗) can't grow or escape — stuck and troubled.","cn":""},
  "遅": {"m":"late, slow, delayed","on":["チ"],"kun":["おそ.い","おく.れる","おく.らす"],"rad":[{"c":"辶","m":"road / movement"},{"c":"尸","m":"body / shelter"},{"c":"羊","m":"sheep"}],"mn":"A sheep (羊) dawdles under the shelter (尸) as the road (辶) waits — always late and slow.","cn":"Japanese 遅, traditional Chinese 遲, simplified Chinese 迟."},
  "連": {"m":"connect, link; a series, run; take (someone) along","on":["レン"],"kun":["つら.なる","つら.ねる","つ.れる"],"rad":[{"c":"辶","m":"road / movement"},{"c":"車","m":"vehicle / cart"}],"mn":"Carts (車) rolling (辶) nose to tail in one long line — linked, connected.","cn":""},
  "絡": {"m":"entwine, coil around; connect, get in touch (連絡)","on":["ラク"],"kun":["から.む","から.まる","から.める"],"rad":[{"c":"糸","m":"thread"},{"c":"各","m":"each"}],"mn":"Threads (糸) winding around each (各) thing they touch — entwine, connect.","cn":""},
  "質": {"m":"quality, nature, substance; matter; pawn (質屋)","on":["シツ","シチ","チ"],"kun":[],"rad":[{"c":"斤斤","m":"two axes / hatchets"},{"c":"貝","m":"shell / money"}],"mn":"Two axes (斤斤) weigh the money-shell (貝) to appraise it — judging its quality.","cn":""},
  "相": {"m":"mutual, each other; appearance, aspect; government minister","on":["ソウ","ショウ"],"kun":["あい"],"rad":[{"c":"木","m":"tree"},{"c":"目","m":"eye"}],"mn":"An eye (目) sizing up a tree (木), and the tree facing back — looking at each other, mutual.","cn":""},
  "談": {"m":"talk, conversation, discussion","on":["ダン"],"kun":[],"rad":[{"c":"言","m":"words / speech"},{"c":"炎","m":"blaze / two fires"}],"mn":"Words (言) flaring like a blaze (炎) back and forth — a warm, lively conversation.","cn":""},
  "練": {"m":"practice, train, drill; knead, refine (silk)","on":["レン"],"kun":["ね.る"],"rad":[{"c":"糸","m":"thread / silk"},{"c":"柬","m":"select, sort out"}],"mn":"Refine raw silk (糸) by sorting out (柬) the best strands — repeated, patient work: practice.","cn":"Simplified Chinese writes this 练; Japanese keeps the fuller 練."},
  "習": {"m":"to learn, practice; custom","on":["シュウ"],"kun":["なら.う"],"rad":[{"c":"羽","m":"feathers / wings"},{"c":"白","m":"white / bright (dawn)"}],"mn":"A fledgling flaps its feathers (羽) toward the white (白) dawn, over and over — that repetition is how you learn.","cn":""},
  "試": {"m":"to try, test, attempt","on":["シ"],"kun":["こころ.みる","ため.す"],"rad":[{"c":"言","m":"words / speech"},{"c":"式","m":"ceremony / set formula"}],"mn":"Put your words (言) to a set formula (式) — you try it out and test whether it holds.","cn":""},
  "格": {"m":"status, rank, standard; (grammatical) case","on":["カク","コウ"],"kun":[],"rad":[{"c":"木","m":"tree / wood"},{"c":"各","m":"each"}],"mn":"Each (各) tree (木) grows to its own height — its rank, standard, and status in the grove.","cn":""},
  "失": {"m":"to lose; fault, mistake","on":["シツ"],"kun":["うしな.う"],"rad":[{"c":"失","m":"a hand letting something slip from its grasp (pictograph)"}],"mn":"A hand with something slipping out of its grip — to lose it, to miss, a mistake.","cn":""},
  "敗": {"m":"defeat, failure; to be defeated","on":["ハイ"],"kun":["やぶ.れる"],"rad":[{"c":"貝","m":"shell / money / treasure"},{"c":"攵","m":"strike / rap (action)"}],"mn":"Rap and strike (攵) at the treasure-shell (貝) until it shatters — ruin, defeat, failure.","cn":"Simplified Chinese writes this 败; Japanese keeps the fuller 敗."},
  "心": {"m":"heart, mind, spirit","on":["シン"],"kun":["こころ"],"rad":[{"c":"心","m":"a heart (pictograph of the organ)"}],"mn":"A simple picture of the physical heart — the seat of mind, feeling, and spirit.","cn":""},
  "配": {"m":"to distribute, hand out, arrange; allot","on":["ハイ"],"kun":["くば.る"],"rad":[{"c":"酉","m":"wine jar / sake vessel"},{"c":"己","m":"self / a kneeling person"}],"mn":"A person (己) kneeling by the wine jar (酉), pouring it out and handing the cups round — to distribute, to arrange.","cn":""},
  "無": {"m":"nothing, nil, without","on":["ム","ブ"],"kun":["な.い"],"rad":[{"c":"舞","m":"a dancer waving thick tassels (original sense)"},{"c":"灬","m":"fire (the four dots)"}],"mn":"A dancer waving thick tassels (as in 舞) above the fire (灬) until everything burns away to nothing.","cn":"Simplified Chinese writes this 无; Japanese (and traditional Chinese) keep the fuller 無."},
  "願": {"m":"wish, request; to pray, hope","on":["ガン"],"kun":["ねが.う"],"rad":[{"c":"原","m":"origin / plain / source"},{"c":"頁","m":"head (the 'big head' radical)"}],"mn":"Bow your head (頁) toward the source of all things (原) and voice your wish — to pray, to request.","cn":""},
  "礼": {"m":"courtesy, etiquette; thanks, a bow","on":["レイ","ライ"],"kun":[],"rad":[{"c":"礻","m":"altar / spirit (ritual radical)"},{"c":"乚","m":"a hook / bending stroke"}],"mn":"At the spirit-altar (礻) you bend low (乚) in a bow — the essence of courtesy, ceremony, and thanks.","cn":"The traditional form is 禮; Japan simplified it to 礼 (mainland Chinese uses 礼 as well)."},
  "客": {"m":"guest, visitor, customer","on":["キャク","カク"],"kun":[],"rad":[{"c":"宀","m":"roof"},{"c":"各","m":"each"}],"mn":"Under the roof (宀) comes each (各) new arrival — a guest, a visitor, a customer.","cn":""},
  "様": {"m":"manner, appearance, way; Mr./Ms. (honorific)","on":["ヨウ"],"kun":["さま"],"rad":[{"c":"木","m":"tree / wood"},{"c":"羊","m":"sheep"},{"c":"水","m":"water"}],"mn":"By the tree (木) a sheep (羊) drinks flowing water (水) — the manner and look of a scene; and, politely, 'Mr./Ms.'","cn":"As a name suffix 〜様 (-sama) is a high-politeness honorific — お客様 'honored customer', 神様 'god'. Traditional shape is 樣."},
  "員": {"m":"member, staff, personnel","on":["イン"],"kun":[],"rad":[{"c":"口","m":"mouth"},{"c":"貝","m":"shell / money"}],"mn":"Mouths (口) gathered around the money (貝) of a business — its members and staff.","cn":""},
  "注": {"m":"to pour; pour attention into, annotate","on":["チュウ"],"kun":["そそ.ぐ"],"rad":[{"c":"氵","m":"water"},{"c":"主","m":"master / main"}],"mn":"The master (主) of the water (氵) tips it into the cup — to pour, and to pour your attention in.","cn":""},
  "平": {"m":"flat, level, even; peace, ordinary","on":["ヘイ","ビョウ"],"kun":["たい.ら","ひら"],"rad":[{"c":"平","m":"two weights balanced even on a beam (pictograph)"}],"mn":"Two weights resting even on the beam of a balance — flat, level, calm, at peace.","cn":""},
  "和": {"m":"harmony, peace; Japanese-style; sum","on":["ワ","オ"],"kun":["やわ.らぐ","なご.む"],"rad":[{"c":"禾","m":"grain / rice plant"},{"c":"口","m":"mouth"}],"mn":"Grain (禾) enough for every mouth (口) — everyone fed, and so harmony and peace.","cn":"In Japanese 和 also means 'Japanese-style': 和食 Japanese food, 和室 tatami room, 和風 Japanese-style — a sense (from 大和 Yamato) the Chinese character lacks."},
  "情": {"m":"feeling, emotion, compassion; circumstances","on":["ジョウ","セイ"],"kun":["なさ.け"],"rad":[{"c":"忄","m":"heart (radical)"},{"c":"青","m":"blue-green / fresh"}],"mn":"A fresh, blue-green (青) stirring in the heart (忄) — raw feeling, emotion, compassion.","cn":""},
  "乾": {"m":"dry; to dry out","on":["カン"],"kun":["かわ.く","かわ.かす"],"rad":[{"c":"日","m":"sun rising over the horizon"},{"c":"乙","m":"a bending sprout / hook"}],"mn":"The rising sun (日) over the horizon, with a hooked sprout (乙), drives off every drop of moisture — dry.","cn":"Simplified Chinese writes 'dry' as 干, so the toast is 干杯 (gānbēi) there; Japanese keeps 乾 — 乾杯 (kanpai). Both mean 'dry the cup'."},
  "杯": {"m":"cup, glass; counter for cupfuls/drinks","on":["ハイ"],"kun":["さかずき"],"rad":[{"c":"木","m":"tree / wood"},{"c":"不","m":"not / no"}],"mn":"A wooden (木) cup — drink it dry and there's 'not' (不) a drop left; raise it for the toast, 乾杯!","cn":""},
  "挨": {"m":"to push, draw near (as in 挨拶, a greeting)","on":["アイ"],"kun":[],"rad":[{"c":"扌","m":"hand"},{"c":"矢","m":"arrow"}],"mn":"Reach out a hand (扌) as straight as an arrow (矢) toward someone — draw near to greet: 挨拶.","cn":""},
  "拶": {"m":"to press, squeeze (paired in 挨拶, a greeting)","on":["サツ"],"kun":[],"rad":[{"c":"扌","m":"hand"},{"c":"巛","m":"curved streams"},{"c":"夕","m":"evening / crescent"}],"mn":"Hands (扌) pressing through crowding streams (巛) at dusk (夕) — the 'squeeze', the second half of 挨拶, 'greeting'.","cn":""},
  "通": {"m":"to pass through, commute; traffic, communicate","on":["ツウ","ツ"],"kun":["とお.る","とお.す","かよ.う"],"rad":[{"c":"辶","m":"road / movement"},{"c":"甬","m":"an open path / channel"}],"mn":"Move (辶) straight along the open path (甬) — to pass through, to commute, to get your meaning across.","cn":""},
  "訳": {"m":"translation; reason, circumstance","on":["ヤク"],"kun":["わけ"],"rad":[{"c":"言","m":"words / speech"},{"c":"尺","m":"measure / ruler"}],"mn":"Measure (尺) words (言) across from one tongue into another — translation; and the 'reason' (わけ) behind them.","cn":"Traditional form is 譯 (simplified Chinese 译); Japan simplified it to 訳. 通訳 is an interpreter; 訳 alone also means 'reason'."},
  "成": {"m":"to become; accomplish, form, complete","on":["セイ","ジョウ"],"kun":["な.る","な.す"],"rad":[{"c":"戈","m":"halberd / weapon"},{"c":"丁","m":"a nail / mark"}],"mn":"Take up the halberd (戈) and drive the task to its mark (丁) — to see it through, to become, to accomplish.","cn":""},
  "功": {"m":"achievement, merit, success, credit","on":["コウ","ク"],"kun":[],"rad":[{"c":"工","m":"work / craft"},{"c":"力","m":"power / strength"}],"mn":"Honest work (工) backed by real strength (力) — the achievement and merit it earns: success.","cn":""}
};
